css:
.fxv-reveal {
  /* re-theme: override paper / ink / accent / water per [data-theme] */
  --fxv-reveal-paper: oklch(0.972 0.014 86);
  --fxv-reveal-ink: oklch(0.255 0.022 58);
  --fxv-reveal-accent: oklch(0.555 0.148 38);
  --fxv-reveal-water: oklch(0.6 0.075 222);
  --fxv-reveal-dim: color-mix(in oklch, var(--fxv-reveal-ink) 64%, var(--fxv-reveal-paper));
  --fxv-reveal-line: color-mix(in oklch, var(--fxv-reveal-ink) 13%, transparent);
  --fxv-reveal-chip: color-mix(in oklch, var(--fxv-reveal-ink) 6%, var(--fxv-reveal-paper));

  container-type: inline-size;
  view-transition-class: fxv-reveal-root;
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  inline-size: 100%;
  max-inline-size: 520px;
  display: grid;
  grid-template-areas: "bar" "kicker" "title" "dek" "tide" "foot";
  row-gap: 8px;
  padding: 16px 18px 14px;
  border-radius: 18px;
  background: var(--fxv-reveal-paper);
  color: var(--fxv-reveal-ink);
  font: 13px/1.45 system-ui, sans-serif;
  box-shadow: 0 1px 0 color-mix(in oklch, var(--fxv-reveal-ink) 8%, transparent) inset,
              0 18px 40px -24px oklch(0.2 0.02 60 / 0.5);

  &[data-theme="dusk"] {
    --fxv-reveal-paper: oklch(0.315 0.058 32);
    --fxv-reveal-ink: oklch(0.935 0.034 74);
    --fxv-reveal-accent: oklch(0.81 0.135 64);
    --fxv-reveal-water: oklch(0.72 0.09 46);
  }
  &[data-theme="night"] {
    --fxv-reveal-paper: oklch(0.185 0.008 85);
    --fxv-reveal-ink: oklch(0.9 0.018 92);
    --fxv-reveal-accent: oklch(0.87 0.105 96);
    --fxv-reveal-water: oklch(0.66 0.045 205);
  }

  & .fxv-reveal-bar {
    grid-area: bar;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding-block-end: 8px;
    border-block-end: 1px solid var(--fxv-reveal-line);
  }
  & .fxv-reveal-mast {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    min-inline-size: 0;
    font: 600 12px/1 ui-serif, Georgia, serif;
    font-variant: small-caps;
    letter-spacing: 0.06em;
    white-space: nowrap;
    & > span { overflow: hidden; text-overflow: ellipsis; }
    & svg {
      inline-size: 18px;
      block-size: 18px;
      flex: none;
      fill: none;
      stroke: var(--fxv-reveal-accent);
      stroke-width: 1.6;
      stroke-linecap: round;
    }
  }
  & .fxv-reveal-modes {
    flex: none;
    display: flex;
    gap: 2px;
    padding: 2px;
    border-radius: 999px;
    background: var(--fxv-reveal-chip);
    box-shadow: inset 0 0 0 1px var(--fxv-reveal-line);
  }
  & .fxv-reveal-modes button {
    all: unset;
    box-sizing: border-box;
    inline-size: 28px;
    block-size: 28px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    cursor: pointer;
    color: var(--fxv-reveal-dim);
    /* transform only: a colour transition would replay inside the live
       new-state snapshot and spoil the reveal */
    transition: transform 0.22s cubic-bezier(0.3, 1.6, 0.5, 1);
    & svg {
      inline-size: 17px;
      block-size: 17px;
      fill: none;
      stroke: currentColor;
      stroke-width: 1.6;
      stroke-linecap: round;
      stroke-linejoin: round;
    }
    &:hover { transform: scale(1.1); color: var(--fxv-reveal-ink); }
    &:active { transform: scale(0.92); }
    &:focus-visible { outline: 2px solid var(--fxv-reveal-accent); outline-offset: 1px; }
    &[aria-checked="true"] {
      background: var(--fxv-reveal-ink);
      color: var(--fxv-reveal-paper);
    }
  }
  & .fxv-reveal-rays {
    transform-origin: 12px 12px;
    animation: fxv-reveal-spin 24s linear infinite;
  }
  & .fxv-reveal-star {
    transform-origin: 17px 6px;
    animation: fxv-reveal-twinkle 3.2s ease-in-out infinite;
  }

  & .fxv-reveal-kicker {
    grid-area: kicker;
    margin: 4px 0 0;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--fxv-reveal-accent);
  }
  & .fxv-reveal-title {
    grid-area: title;
    margin: 0;
    font: 600 clamp(19px, 7cqi, 27px)/1.08 ui-serif, Georgia, serif;
    letter-spacing: -0.012em;
    text-wrap: balance;
  }
  & .fxv-reveal-dek {
    grid-area: dek;
    margin: 0;
    color: var(--fxv-reveal-dim);
    font-size: clamp(12px, 3.9cqi, 13.5px);
    text-wrap: pretty;
  }

  & .fxv-reveal-tide {
    grid-area: tide;
    margin: 2px 0 0;
    & .fxv-reveal-plot { position: relative; }
    & svg {
      display: block;
      inline-size: 100%;
      block-size: 50px;
      overflow: visible;
    }
    & figcaption {
      display: flex;
      justify-content: space-between;
      gap: 8px;
      margin-block-start: 6px;
      font: 10.5px/1.2 ui-monospace, Menlo, monospace;
      font-variant-numeric: tabular-nums;
      color: var(--fxv-reveal-dim);
      & b { color: var(--fxv-reveal-ink); font-weight: 600; }
      & i { font-style: normal; }
    }
  }
  & .fxv-reveal-area {
    fill: color-mix(in oklch, var(--fxv-reveal-water) 22%, transparent);
    transform-box: fill-box;
    transform-origin: 50% 100%;
    animation: fxv-reveal-swell 5s ease-in-out infinite alternate;
  }
  & .fxv-reveal-line {
    fill: none;
    stroke: var(--fxv-reveal-water);
    stroke-width: 1.6;
    vector-effect: non-scaling-stroke;
  }
  & .fxv-reveal-nowline {
    stroke: var(--fxv-reveal-accent);
    stroke-width: 1;
    stroke-dasharray: 2 3;
    vector-effect: non-scaling-stroke;
  }
  & .fxv-reveal-dot {
    position: absolute;
    inline-size: 9px;
    block-size: 9px;
    margin: -4.5px 0 0 -4.5px;
    border-radius: 50%;
    background: var(--fxv-reveal-accent);
    box-shadow: 0 0 0 2px var(--fxv-reveal-paper);
    &::after {
      content: "";
      position: absolute;
      inset: -5px;
      border-radius: 50%;
      border: 1.5px solid var(--fxv-reveal-accent);
      animation: fxv-reveal-ping 2.4s cubic-bezier(0.2, 0.7, 0.3, 1) infinite;
    }
  }
  & .fxv-reveal-now {
    position: absolute;
    top: -2px;
    font: 10px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxv-reveal-dim);
    white-space: nowrap;
    & i { font-style: normal; }
    & b { color: var(--fxv-reveal-accent); font-weight: 600; }
  }
  & .fxv-reveal-foot {
    grid-area: foot;
    display: flex;
    justify-content: space-between;
    padding-block-start: 8px;
    border-block-start: 1px solid var(--fxv-reveal-line);
    font-size: 11px;
    color: var(--fxv-reveal-dim);
    & span:first-child { color: var(--fxv-reveal-ink); font-weight: 600; }
  }
}

@container (inline-size < 330px) {
  .fxv-reveal .fxv-reveal-tide figcaption span:is(:first-child, :last-child) { display: none; }
}
@container (inline-size < 260px) {
  .fxv-reveal .fxv-reveal-now i { display: none; }
}
@container (inline-size < 300px) {
  .fxv-reveal .fxv-reveal-mast { font-size: 11px; }
  .fxv-reveal .fxv-reveal-modes button { inline-size: 26px; block-size: 26px; }

}

/* The reveal: both snapshots are held still; the script grows a clip-path
   circle on the new one from the click point and dims the old one. */
::view-transition-group(.fxv-reveal-root) { animation-duration: 0.72s; }
::view-transition-old(.fxv-reveal-root),
::view-transition-new(.fxv-reveal-root) {
  animation: none;
  mix-blend-mode: normal;
}

@keyframes fxv-reveal-spin { to { transform: rotate(360deg); } }
@keyframes fxv-reveal-twinkle { 0%, 100% { opacity: 0.25; transform: scale(0.6); } 50% { opacity: 1; transform: scale(1); } }
@keyframes fxv-reveal-swell { from { transform: scaleY(0.94); } to { transform: scaleY(1.03); } }
@keyframes fxv-reveal-ping {
  0% { transform: scale(0.5); opacity: 0.9; }
  70%, 100% { transform: scale(1.6); opacity: 0; }
}
@keyframes fxv-reveal-fade-in { from { opacity: 0; } }

@media (prefers-reduced-motion: reduce) {
  .fxv-reveal {
    & .fxv-reveal-rays, & .fxv-reveal-star, & .fxv-reveal-area { animation: none; }
    & .fxv-reveal-star { opacity: 1; }
    & .fxv-reveal-dot::after { animation: none; transform: scale(1.2); opacity: 0.35; }
    & .fxv-reveal-modes button { transition: none; }
  }
  /* calm version: the new theme fades in over the old one, no circle */
  ::view-transition-new(.fxv-reveal-root) { animation: fxv-reveal-fade-in 0.22s ease both; }
}

js:
/* ── view-transition plumbing ─────────────────────────────────────────
   1. root.startViewTransition()     scoped: snapshots only this component, clips
                                      to it, and leaves the rest of the page live
   2. document.startViewTransition() whole-document snapshot; the root is named
                                      for the duration so it animates as one group
   3. FLIP with the Web Animations API when neither exists
   Names carry a per-instance id so two copies on one page never collide.  */
const ID = 'fxv-reveal';
const UID = Math.random().toString(36).slice(2, 8);
const ROOT_NAME = ID + '-' + UID;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SCOPED = typeof root.startViewTransition === 'function';
const DOCVT = typeof document.startViewTransition === 'function';
const vtName = key => ROOT_NAME + '-' + key;
const host = () => (SCOPED ? root : document.documentElement);
let running = null;

function nameParts(on) {
  root.querySelectorAll('[data-vt]').forEach(el => {
    el.style.viewTransitionName = on && !RM.matches && el.getClientRects().length ? vtName(el.dataset.vt) : '';
  });
}

function morph(update, onReady, onAbort) {
  if (!SCOPED && !DOCVT) { flip(update); return null; }
  const first = measure();
  nameParts(true);
  root.style.viewTransitionName = ROOT_NAME;
  const run = () => { update(); nameParts(true); };
  const t = SCOPED ? root.startViewTransition(run) : document.startViewTransition(run);
  running = t;
  t.ready.then(() => { if (onReady && !RM.matches) onReady(t); }, e => {
    /* An AbortError just means a newer transition took over. Chrome can also
       abort a scoped transition with InvalidStateError while others run on
       the page; the DOM still updates, so replay the change instead of letting
       it snap: FLIP from the geometry measured above, or the caller's own. */
    if (!e || e.name !== 'InvalidStateError' || RM.matches) return;
    t.updateCallbackDone.then(() => (onAbort ? onAbort() : play(first)), () => {});
  });
  t.finished.finally(() => {
    if (running !== t) return;
    running = null;
    nameParts(false);
    root.style.viewTransitionName = '';
  });
  return t;
}

/* Animate one of this transition's pseudo-elements from script. */
function pseudo(part, key, keyframes, opts) {
  const name = key === 'root' ? ROOT_NAME : vtName(key);
  return host().animate(keyframes, Object.assign({ fill: 'both' }, opts, { pseudoElement: '::view-transition-' + part + '(' + name + ')' }));
}

/* All running animations that belong to one of our named groups. */
function ownAnimations() {
  return host().getAnimations({ subtree: true }).filter(a => {
    const p = a.effect && a.effect.pseudoElement;
    return p && p.indexOf(ROOT_NAME + '-') > -1;
  });
}

const measure = () => null;
const play = () => {};
function flip(update) { update(); }

const modes = [...root.querySelectorAll('[data-mode]')];

function apply(btn) {
  root.dataset.theme = btn.dataset.mode;
  modes.forEach(b => {
    const on = b === btn;
    b.setAttribute('aria-checked', on ? 'true' : 'false');
    b.tabIndex = on ? 0 : -1;
  });
}

/* x, y are relative to the root's border box — the same box the root's
   snapshot group is sized to, so they can go straight into circle(). */
function reveal(btn, x, y) {
  if (root.dataset.theme === btn.dataset.mode) return;
  if (!SCOPED && !DOCVT) { apply(btn); return; }
  const r = root.getBoundingClientRect();
  const R = Math.ceil(Math.hypot(Math.max(x, r.width - x), Math.max(y, r.height - y)));
  morph(() => apply(btn), () => {
    const timing = { duration: 720, easing: 'cubic-bezier(.65,.05,.25,1)' };
    pseudo('new', 'root', {
      clipPath: ['circle(0px at ' + x + 'px ' + y + 'px)', 'circle(' + R + 'px at ' + x + 'px ' + y + 'px)']
    }, timing);
    pseudo('old', 'root', { filter: ['brightness(1)', 'brightness(.8)'] }, timing);
  });
}

function centreOf(btn) {
  const r = root.getBoundingClientRect(), b = btn.getBoundingClientRect();
  return [b.left + b.width / 2 - r.left, b.top + b.height / 2 - r.top];
}

root.addEventListener('click', e => {
  const btn = e.target.closest('[data-mode]');
  if (!btn) return;
  /* a keyboard "click" has detail 0 and no meaningful coordinates */
  if (e.detail === 0) { reveal(btn, ...centreOf(btn)); return; }
  const r = root.getBoundingClientRect();
  reveal(btn, e.clientX - r.left, e.clientY - r.top);
});

root.querySelector('.fxv-reveal-modes').addEventListener('keydown', e => {
  const i = modes.indexOf(document.activeElement);
  if (i < 0) return;
  let j = -1;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = (i + 1) % modes.length;
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = (i - 1 + modes.length) % modes.length;
  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = modes.length - 1;
  if (j < 0) return;
  e.preventDefault();
  modes[j].focus();
  reveal(modes[j], ...centreOf(modes[j]));
});

css:
.fxv-wallet {
  --fxv-wallet-bg: oklch(0.205 0.012 58);
  --fxv-wallet-ink: oklch(0.94 0.012 80);
  --fxv-wallet-accent: oklch(0.82 0.11 82);
  --fxv-wallet-dim: color-mix(in oklch, var(--fxv-wallet-ink) 55%, var(--fxv-wallet-bg));
  --fxv-wallet-line: color-mix(in oklch, var(--fxv-wallet-ink) 12%, transparent);
  --fxv-wallet-step: 54px;      /* visible strip of a stacked pass */
  --fxv-wallet-face: 150px;     /* pass height at rest */
  --fxv-wallet-full: 226px;     /* pass height when opened */

  container-type: inline-size;
  view-transition-class: fxv-wallet-root;
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  inline-size: 100%;
  max-inline-size: 440px;
  display: grid;
  grid-template-rows: auto auto;
  row-gap: 12px;
  padding: 14px 14px 16px;
  border-radius: 20px;
  color: var(--fxv-wallet-ink);
  font: 13px/1.35 system-ui, sans-serif;
  background:
    radial-gradient(120% 80% at 20% 0%, color-mix(in oklch, var(--fxv-wallet-ink) 6%, transparent), transparent 60%),
    var(--fxv-wallet-bg);
  box-shadow: inset 0 0 0 1px var(--fxv-wallet-line);

  & .fxv-wallet-head {
    display: flex;
    align-items: baseline;
    gap: 8px;
    padding-inline: 2px;
    min-block-size: 26px;
    & h3 { margin: 0; font-size: 17px; font-weight: 700; letter-spacing: -0.01em; }
  }
  & .fxv-wallet-count {
    color: var(--fxv-wallet-dim);
    font-size: 12px;
    font-variant-numeric: tabular-nums;
  }
  & .fxv-wallet-done {
    all: unset;
    margin-inline-start: auto;
    padding: 4px 11px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 600;
    color: var(--fxv-wallet-bg);
    background: var(--fxv-wallet-accent);
    cursor: pointer;
    visibility: hidden;
    &:focus-visible { outline: 2px solid var(--fxv-wallet-accent); outline-offset: 2px; }
  }
  &:has(.fxv-wallet-pass[aria-current]) .fxv-wallet-done { visibility: visible; }

  & .fxv-wallet-stack {
    position: relative;
    block-size: max(calc(var(--fxv-wallet-step) * 3 + var(--fxv-wallet-face)),
                    calc(var(--fxv-wallet-full) + 34px + var(--fxv-wallet-step) * 0.94));
  }

  & .fxv-wallet-pass {
    --y: calc(var(--i) * var(--fxv-wallet-step));
    position: absolute;
    inset-inline: 0;
    top: var(--y);
    block-size: var(--fxv-wallet-face);
    box-sizing: border-box;
    border-radius: 16px;
    overflow: hidden;
    color: var(--fxv-wallet-on);
    background:
      linear-gradient(160deg, oklch(1 0 0 / 0.16), transparent 42%),
      var(--fxv-wallet-c);
    box-shadow: 0 -1px 0 oklch(1 0 0 / 0.18) inset, 0 -8px 18px -10px oklch(0 0 0 / 0.55);
    cursor: pointer;
    view-transition-class: fxv-wallet-card;
    transition: translate 0.3s cubic-bezier(0.3, 1.5, 0.5, 1);
    &:not([aria-current]):hover { translate: 0 -7px; }
    &:last-child::after, &[aria-current]::after {
      content: "";
      position: absolute;
      inset: -40% -60%;
      background: linear-gradient(105deg, transparent 42%, oklch(1 0 0 / 0.2) 50%, transparent 58%);
      transform: translateX(-60%);
      animation: fxv-wallet-sheen 6.5s cubic-bezier(0.45, 0, 0.2, 1) 1.2s infinite;
      pointer-events: none;
    }
  }

  /* opened: the chosen pass rises to the top and grows, the rest fold into a
     shallow deck at the bottom — every move is the view transition's job */
  &:has(.fxv-wallet-pass[aria-current]) .fxv-wallet-pass {
    --y: calc(var(--fxv-wallet-full) + 10px + var(--k, 0) * 12px);
    block-size: var(--fxv-wallet-step);
    scale: 0.94;
    transform-origin: 50% 0;
    &::after { content: none; }
    &[aria-current] {
      --y: 0px;
      block-size: var(--fxv-wallet-full);
      scale: 1;
      cursor: default;
      &::after { content: ""; }
    }
  }

  & .fxv-wallet-strip {
    all: unset;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    gap: 9px;
    inline-size: 100%;
    block-size: var(--fxv-wallet-step);
    padding: 0 14px;
    cursor: inherit;
    &:focus-visible { outline: 2px solid var(--fxv-wallet-on); outline-offset: -5px; border-radius: 14px; }
  }
  & .fxv-wallet-glyph {
    inline-size: 20px;
    block-size: 20px;
    flex: none;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.6;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  & .fxv-wallet-issuer {
    flex: 1;
    min-inline-size: 0;
    font-weight: 650;
    font-size: 13px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  & .fxv-wallet-key {
    display: grid;
    justify-items: end;
    font: 600 15px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    & small {
      font: 600 9px/1.4 system-ui, sans-serif;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      opacity: 0.72;
    }
  }

  & .fxv-wallet-body {
    display: grid;
    gap: 12px;
    padding: 2px 14px 14px;
  }
  & .fxv-wallet-primary {
    margin: 0;
    display: grid;
    & small {
      font-size: 10px;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      opacity: 0.72;
    }
    & b {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: clamp(20px, 8.2cqi, 28px);
      font-weight: 750;
      letter-spacing: -0.02em;
      line-height: 1.1;
      white-space: nowrap;
    }
    & svg {
      inline-size: 0.8em;
      block-size: 0.8em;
      fill: none;
      stroke: currentColor;
      stroke-width: 2.2;
      stroke-linecap: round;
      stroke-linejoin: round;
      opacity: 0.8;
    }
  }
  & .fxv-wallet-fields {
    margin: 0;
    display: grid;
    grid-template-columns: repeat(4, auto);
    justify-content: space-between;
    gap: 8px;
    & div { display: grid; gap: 2px; min-inline-size: 0; }
    & dt {
      font-size: 9px;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      opacity: 0.72;
    }
    & dd {
      margin: 0;
      font-weight: 650;
      font-size: 12.5px;
      font-variant-numeric: tabular-nums;
      white-space: nowrap;
    }
  }
  & .fxv-wallet-code {
    display: flex;
    align-items: center;
    gap: 12px;
    padding-block-start: 12px;
    border-block-start: 1px dashed color-mix(in oklch, var(--fxv-wallet-on) 35%, transparent);
    & svg {
      inline-size: 52px;
      block-size: 52px;
      flex: none;
      padding: 4px;
      border-radius: 6px;
      background: oklch(0.985 0.005 90);
      & path { fill: oklch(0.2 0.01 60); }
    }
    & p {
      margin: 0;
      font-size: 11.5px;
      line-height: 1.4;
      opacity: 0.85;
      text-wrap: pretty;
    }
  }
}

@container (inline-size < 280px) {
  .fxv-wallet .fxv-wallet-stack { --fxv-wallet-full: 262px; --fxv-wallet-face: 184px; }
  .fxv-wallet .fxv-wallet-fields { grid-template-columns: repeat(2, auto); justify-content: start; column-gap: 22px; }
