  const first = measure();
  update();
  play(first);
}

const passes = [...root.querySelectorAll('.fxv-wallet-pass')];
const strips = passes.map(p => p.querySelector('.fxv-wallet-strip'));
const done = root.querySelector('.fxv-wallet-done');
let open = null;

