/* A deterministic 25×25 matrix code per pass: three finder squares plus a
   seeded fill, drawn as one path so it costs a single element. */
passes.forEach(p => {
  let s = [...p.dataset.key].reduce((a, ch) => (a * 31 + ch.charCodeAt(0)) >>> 0, 2166136261);
  const rnd = () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
  const finder = (x, y) => {
    const dx = x - (x < 12 ? 0 : 18), dy = y - (y < 12 ? 0 : 18);
    if (dx < 0 || dx > 6 || dy < 0 || dy > 6) return null;
    return dx === 0 || dx === 6 || dy === 0 || dy === 6 || (dx > 1 && dx < 5 && dy > 1 && dy < 5);
  };
  let d = '';
  for (let y = 0; y < 25; y++) for (let x = 0; x < 25; x++) {
    const inF = (x < 8 && y < 8) || (x > 16 && y < 8) || (x < 8 && y > 16);
    const on = inF ? finder(x, y) : rnd() < 0.47;
