function choose(p) {
  if (p === open) return;
  morph(() => { open = p; render(); });
}

root.addEventListener('click', e => {
  if (e.target.closest('.fxv-wallet-done')) { const was = open; choose(null); if (was) was.querySelector('.fxv-wallet-strip').focus(); return; }
  const p = e.target.closest('.fxv-wallet-pass');
  if (!p) return;
  if (p === open) { if (e.target.closest('.fxv-wallet-strip')) choose(null); return; }
  choose(p);
  if (!e.target.closest('.fxv-wallet-strip')) p.querySelector('.fxv-wallet-strip').focus({ preventScroll: true });
});

root.addEventListener('keydown', e => {
  if (e.key === 'Escape' && open) {
    e.preventDefault();
    const was = open;
    choose(null);
    was.querySelector('.fxv-wallet-strip').focus();
    return;
  }
  const i = strips.indexOf(document.activeElement);
  if (i < 0) return;
  let j = -1;
  if (e.key === 'ArrowDown') j = Math.min(i + 1, strips.length - 1);
  else if (e.key === 'ArrowUp') j = Math.max(i - 1, 0);
  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = strips.length - 1;
  if (j < 0) return;
  e.preventDefault();
  strips[j].focus();
  if (open) choose(passes[j]);
});

render();

