.fxv-chroma {
  --fxv-chroma-paper: oklch(0.977 0.006 88);
  --fxv-chroma-ink: oklch(0.23 0.012 70);
  --fxv-chroma-accent: oklch(0.45 0.17 272);
  --fxv-chroma-dim: color-mix(in oklch, var(--fxv-chroma-ink) 58%, var(--fxv-chroma-paper));
  --fxv-chroma-line: color-mix(in oklch, var(--fxv-chroma-ink) 12%, transparent);
  --fxv-chroma-well: color-mix(in oklch, var(--fxv-chroma-ink) 5%, var(--fxv-chroma-paper));

  container-type: inline-size;
  view-transition-class: fxv-chroma-root;
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  inline-size: 100%;
  max-inline-size: 560px;
  display: grid;
  grid-template-areas: "head" "sort" "fams" "grid" "detail";
  row-gap: 10px;
  padding: 16px;
  border-radius: 18px;
  background: var(--fxv-chroma-paper);
  color: var(--fxv-chroma-ink);
  font: 12.5px/1.35 system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxv-chroma-line);

  & .fxv-chroma-head {
    grid-area: head;
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    & h3 { margin: 0; font-size: 15px; font-weight: 750; letter-spacing: -0.01em; }
  }
  & .fxv-chroma-count {
    margin: 0;
    color: var(--fxv-chroma-dim);
    font: 11px/1 ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    & b { color: var(--fxv-chroma-ink); font-weight: 600; }
  }

  & .fxv-chroma-sort {
    grid-area: sort;
    position: relative;
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: 1fr;
    padding: 3px;
    border-radius: 10px;
    background: var(--fxv-chroma-well);
    box-shadow: inset 0 0 0 1px var(--fxv-chroma-line);
    & button {
      all: unset;
      grid-row: 1;
      view-transition-class: fxv-chroma-seg;
      padding: 6px 4px;
      border-radius: 7px;
      text-align: center;
      font-weight: 600;
      font-size: 12px;
      color: var(--fxv-chroma-dim);
      cursor: pointer;
      &:hover { color: var(--fxv-chroma-ink); }
      &:focus-visible { outline: 2px solid var(--fxv-chroma-accent); outline-offset: -2px; }
      &[aria-checked="true"] { color: var(--fxv-chroma-ink); }
    }
  }
  /* every segment sits in an explicit column and the pill takes the checked
     one's; the pill comes first in the DOM, so in the transition its group is
     painted under the segments' groups and never hides a label */
  & .fxv-chroma-pill {
    grid-row: 1;
    grid-column: var(--fxv-chroma-at, 1);
    border-radius: 7px;
    background: var(--fxv-chroma-paper);
    box-shadow: 0 1px 2px oklch(0.2 0.02 70 / 0.16), 0 0 0 1px var(--fxv-chroma-line);
    view-transition-class: fxv-chroma-pill;
  }

  & .fxv-chroma-fams {
    grid-area: fams;
    display: grid;
    grid-template-columns: repeat(4, auto);
    justify-content: space-between;
    gap: 4px;
  }
  & .fxv-chroma-chip {
    all: unset;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    padding: 4px 8px 4px 6px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    color: var(--fxv-chroma-dim);
    box-shadow: inset 0 0 0 1px var(--fxv-chroma-line);
    cursor: pointer;
    transition: scale 0.18s cubic-bezier(0.3, 1.6, 0.5, 1);
    & i {
      inline-size: 9px;
      block-size: 9px;
      flex: none;
      border-radius: 50%;
      box-shadow: inset 0 0 0 1.5px var(--fxv-chroma-c);
    }
    &[aria-pressed="true"] {
      color: var(--fxv-chroma-ink);
      background: color-mix(in oklch, var(--fxv-chroma-c) 10%, var(--fxv-chroma-paper));
      box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--fxv-chroma-c) 45%, transparent);
      & i { background: var(--fxv-chroma-c); }
    }
    &:hover { color: var(--fxv-chroma-ink); }
    &:active { scale: 0.94; }
    &:focus-visible { outline: 2px solid var(--fxv-chroma-accent); outline-offset: 2px; }
  }

  & .fxv-chroma-grid {
    grid-area: grid;
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 6px;
    /* four rows of square tiles, held so filtering never changes the height */
    min-block-size: calc((100cqi - 30px) / 6 * 4 + 18px);
    align-content: start;
  }
  & .fxv-chroma-tile {
    all: unset;
    aspect-ratio: 1;
    border-radius: 8px;
    background:
      linear-gradient(150deg, oklch(1 0 0 / 0.22), transparent 45%),
      var(--fxv-chroma-c);
    box-shadow: inset 0 0 0 1px oklch(0 0 0 / 0.08), 0 1px 2px oklch(0.2 0.02 70 / 0.14);
    cursor: pointer;
    view-transition-class: fxv-chroma-tile;
    transition: scale 0.25s cubic-bezier(0.3, 1.5, 0.5, 1), box-shadow 0.25s;
    &:hover, &:focus-visible {
      scale: 1.12;
      position: relative;
      z-index: 2;
      box-shadow: inset 0 0 0 1px oklch(0 0 0 / 0.08), 0 6px 14px -4px oklch(0.2 0.02 70 / 0.4);
    }
    &:focus-visible { outline: 2px solid var(--fxv-chroma-ink); outline-offset: 2px; }
    &[hidden] { display: none; }
  }
  & .fxv-chroma-empty {
    display: none;
    grid-column: 1 / -1;
    margin: 0;
    padding: 28px 0;
    text-align: center;
    color: var(--fxv-chroma-dim);
  }
  & .fxv-chroma-grid:not(:has(.fxv-chroma-tile:not([hidden]))) .fxv-chroma-empty { display: block; }

  & .fxv-chroma-detail {
    grid-area: detail;
    display: flex;
    align-items: center;
    gap: 7px;
    margin: 0;
    padding-block-start: 10px;
    border-block-start: 1px solid var(--fxv-chroma-line);
    min-inline-size: 0;
    white-space: nowrap;
    & i {
      inline-size: 14px;
      block-size: 14px;
      flex: none;
      border-radius: 4px;
      background: var(--fxv-chroma-c, transparent);
      box-shadow: inset 0 0 0 1px oklch(0 0 0 / 0.1);
    }
    & b { font-weight: 650; }
    & span {
      color: var(--fxv-chroma-dim);
      font-size: 10.5px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }
    & code {
      margin-inline-start: auto;
      font: 11px ui-monospace, Menlo, monospace;
      font-variant-numeric: tabular-nums;
      color: var(--fxv-chroma-dim);
      overflow: hidden;
      text-overflow: ellipsis;
    }
  }
}

@container (inline-size > 430px) {
  .fxv-chroma .fxv-chroma-grid { grid-template-columns: repeat(8, 1fr); min-block-size: calc((100cqi - 42px) / 8 * 3 + 12px); }
}
@container (inline-size < 280px) {
  .fxv-chroma .fxv-chroma-fams { display: flex; flex-wrap: wrap; }
  .fxv-chroma .fxv-chroma-chip { padding-inline: 6px 8px; }
  .fxv-chroma .fxv-chroma-sort button { font-size: 10.5px; padding-inline: 2px; }
}
@container (inline-size < 270px) {
  .fxv-chroma .fxv-chroma-detail span { display: none; }
}

/* Tiles glide on a spring; the script staggers each one by its new diagonal.
   A tile that only exists on one side of the change scales in or out. */
::view-transition-group(.fxv-chroma-tile) {
  animation-duration: 0.62s;
  animation-timing-function: linear(0, 0.026, 0.091, 0.181, 0.285, 0.393, 0.499, 0.598, 0.688, 0.766, 0.833, 0.889, 0.933, 0.968, 0.995, 1.013, 1.026, 1.034, 1.038, 1.038, 1.037, 1.034, 1.031, 1.027, 1.023, 1.019, 1.015, 1.012, 1.009, 1.006, 1);
}
::view-transition-new(.fxv-chroma-tile):only-child {
  animation: fxv-chroma-in 0.46s cubic-bezier(0.2, 0.9, 0.3, 1.25) both;
}
::view-transition-old(.fxv-chroma-tile):only-child {
  animation: fxv-chroma-out 0.26s cubic-bezier(0.5, 0, 0.9, 0.4) both;
}
::view-transition-group(.fxv-chroma-pill) {
  animation-duration: 0.46s;
  animation-timing-function: linear(0, 0.026, 0.091, 0.181, 0.285, 0.393, 0.499, 0.598, 0.688, 0.766, 0.833, 0.889, 0.933, 0.968, 0.995, 1.013, 1.026, 1.034, 1.038, 1.038, 1.037, 1.034, 1.031, 1.027, 1.023, 1.019, 1.015, 1.012, 1.009, 1.006, 1);
}
::view-transition-group(.fxv-chroma-seg) { animation-duration: 0.3s; }
::view-transition-group(.fxv-chroma-root) { animation-duration: 0.3s; }

@keyframes fxv-chroma-in {
  from { opacity: 0; transform: scale(0.3) rotate(-8deg); }
}
@keyframes fxv-chroma-out {
  to { opacity: 0; transform: scale(0.3) rotate(8deg); }
}

@media (prefers-reduced-motion: reduce) {
  .fxv-chroma .fxv-chroma-tile, .fxv-chroma .fxv-chroma-chip { transition: none; }
  .fxv-chroma .fxv-chroma-tile:hover { scale: 1; }
  ::view-transition-group(.fxv-chroma-root) { animation-duration: 0.18s; }
}

