      transformOrigin: ['0 0', '0 0'],
      transform: ['translate(' + dx + 'px,' + dy + 'px) scale(' + sx + ',' + sy + ')', 'none']
    }, { duration: 520, easing: 'cubic-bezier(.2,.9,.25,1)' });
  });
}
function flip(update) {
  const first = measure();
  update();
  play(first);
}

const grid = root.querySelector('.fxv-chroma-grid');
const tiles = [...grid.querySelectorAll('.fxv-chroma-tile')];
const sorts = [...root.querySelectorAll('[data-sort]')];
const chips = [...root.querySelectorAll('.fxv-chroma-chip')];
const detail = root.querySelector('.fxv-chroma-detail');
const countB = root.querySelector('.fxv-chroma-count b');
const sortBox = root.querySelector('.fxv-chroma-sort');

/* read L C h back from each tile's own custom property, so the data lives once */
const info = new Map(tiles.map(t => {
  const m = t.style.getPropertyValue('--fxv-chroma-c').match(/oklch\(([\d.]+) ([\d.]+) ([\d.]+)\)/);
  return [t, { name: t.getAttribute('aria-label').split(',')[0], fam: t.dataset.fam, L: +m[1], C: +m[2], h: +m[3], css: m[0] }];
}));
const by = {
  hue: (a, b) => {
    const A = info.get(a), B = info.get(b), na = A.C < 0.03, nb = B.C < 0.03;
    if (na !== nb) return na ? 1 : -1;          /* greys go last, dark to light */
    if (na) return A.L - B.L;
    return ((A.h - 18 + 360) % 360) - ((B.h - 18 + 360) % 360);
  },
  light: (a, b) => info.get(a).L - info.get(b).L,
  chroma: (a, b) => info.get(b).C - info.get(a).C,
  name: (a, b) => info.get(a).name.localeCompare(info.get(b).name)
};
let sort = 'hue';
const shown = new Set(chips.map(c => c.dataset.fam));

function show(t) {
  const d = info.get(t);
  detail.style.setProperty('--fxv-chroma-c', d.css);
  detail.querySelector('b').textContent = d.name;
  detail.querySelector('span').textContent = d.fam;
  detail.querySelector('code').textContent = d.css;
}

function render() {
  const order = tiles.slice().sort(by[sort]);
  order.forEach(t => grid.insertBefore(t, grid.lastElementChild));
  let n = 0;
  tiles.forEach(t => { t.hidden = !shown.has(t.dataset.fam); if (!t.hidden) n++; });
  countB.textContent = n;
  sorts.forEach(b => {
    const on = b.dataset.sort === sort;
    b.setAttribute('aria-checked', on ? 'true' : 'false');
    b.tabIndex = on ? 0 : -1;
    if (on) sortBox.style.setProperty('--fxv-chroma-at', b.style.gridColumnStart);
  });
  chips.forEach(c => c.setAttribute('aria-pressed', shown.has(c.dataset.fam) ? 'true' : 'false'));
  /* keep exactly one visible tile in the tab order */
  const vis = order.filter(t => !t.hidden);
  if (vis.length && !vis.some(t => t.tabIndex === 0)) tiles.forEach(t => (t.tabIndex = t === vis[0] ? 0 : -1));
}

/* Stagger: delay every animation of a tile's group by its new row + column,
   so the reshuffle sweeps across the grid as a diagonal wave. */
function stagger() {
  const cols = getComputedStyle(grid).gridTemplateColumns.split(' ').length;
  const slot = new Map();
  [...grid.querySelectorAll('.fxv-chroma-tile:not([hidden])')].forEach((t, i) => slot.set(vtName(t.dataset.vt), (i % cols) + Math.floor(i / cols)));
  ownAnimations().forEach(a => {
    const m = a.effect.pseudoElement.match(/\(([^)]+)\)/);
    const d = m && slot.get(m[1]);
    if (d) a.effect.updateTiming({ delay: d * 26 });
  });
}

function change(fn) {
  morph(() => { fn(); render(); }, stagger);
}

root.addEventListener('click', e => {
  const s = e.target.closest('[data-sort]');
  if (s && s.dataset.sort !== sort) { change(() => { sort = s.dataset.sort; }); return; }
  const c = e.target.closest('.fxv-chroma-chip');
  if (c) {
    const f = c.dataset.fam;
    change(() => { shown.has(f) ? shown.delete(f) : shown.add(f); });
    return;
  }
  const t = e.target.closest('.fxv-chroma-tile');
  if (t) show(t);
});
grid.addEventListener('pointerover', e => { const t = e.target.closest('.fxv-chroma-tile'); if (t) show(t); });
grid.addEventListener('focusin', e => { const t = e.target.closest('.fxv-chroma-tile'); if (t) show(t); });

root.addEventListener('keydown', e => {
  const k = e.key;
  const si = sorts.indexOf(document.activeElement);
  if (si > -1) {
    const d = k === 'ArrowRight' || k === 'ArrowDown' ? 1 : k === 'ArrowLeft' || k === 'ArrowUp' ? -1 : 0;
    if (!d) return;
    e.preventDefault();
    const n = sorts[(si + d + sorts.length) % sorts.length];
    n.focus();
    change(() => { sort = n.dataset.sort; });
    return;
  }
  const t = document.activeElement;
  if (!t || !t.classList || !t.classList.contains('fxv-chroma-tile')) return;
  const vis = [...grid.querySelectorAll('.fxv-chroma-tile:not([hidden])')];
  const cols = getComputedStyle(grid).gridTemplateColumns.split(' ').length;
  const i = vis.indexOf(t);
  let j = -1;
  if (k === 'ArrowRight') j = i + 1;
  else if (k === 'ArrowLeft') j = i - 1;
  else if (k === 'ArrowDown') j = i + cols;
  else if (k === 'ArrowUp') j = i - cols;
  else if (k === 'Home') j = 0;
  else if (k === 'End') j = vis.length - 1;
  if (j < 0 || j >= vis.length) return;
  e.preventDefault();
  t.tabIndex = -1;
  vis[j].tabIndex = 0;
  vis[j].focus();
});

/* Idle demo: until someone touches it, the archive re-sorts itself every few
   seconds while it is on screen. Any interaction ends the demo for good. */
let demo = !RM.matches, inView = false, timer = 0;
const cycle = ['hue', 'light', 'chroma', 'name'];
function tick() {
  if (!root.isConnected) return;
  if (!demo) return;
  if (inView && !document.hidden) change(() => { sort = cycle[(cycle.indexOf(sort) + 1) % cycle.length]; });
}
const stopDemo = () => { demo = false; clearInterval(timer); };
['pointerdown', 'keydown', 'focusin'].forEach(ev => root.addEventListener(ev, stopDemo, { once: true }));
if (demo) {
  timer = setInterval(() => { if (!root.isConnected) { clearInterval(timer); return; } tick(); }, 4200);
  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver(es => { inView = es[0].isIntersecting; if (!root.isConnected) io.disconnect(); });
    io.observe(root);
  } else inView = true;
}

render();
show(tiles[0]);

css:
.fxv-zoom {
  --fxv-zoom-paper: oklch(0.984 0.006 95);
  --fxv-zoom-ink: oklch(0.235 0.022 255);
  --fxv-zoom-accent: oklch(0.61 0.19 30);
  --fxv-zoom-studio: oklch(0.66 0.13 58);
  --fxv-zoom-class: oklch(0.6 0.11 160);
  --fxv-zoom-personal: oklch(0.58 0.11 245);
  --fxv-zoom-dim: color-mix(in oklch, var(--fxv-zoom-ink) 52%, var(--fxv-zoom-paper));
  --fxv-zoom-line: color-mix(in oklch, var(--fxv-zoom-ink) 10%, transparent);
  --fxv-zoom-well: color-mix(in oklch, var(--fxv-zoom-ink) 4%, var(--fxv-zoom-paper));
  --fxv-zoom-hour: 18px;

  container-type: inline-size;
  view-transition-class: fxv-zoom-root;
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  inline-size: 100%;
  max-inline-size: 480px;
  display: grid;
  grid-template-areas: "head" "view" "legend";
  row-gap: 10px;
  padding: 14px 14px 12px;
  border-radius: 18px;
  background: var(--fxv-zoom-paper);
  color: var(--fxv-zoom-ink);
  font: 12px/1.35 system-ui, sans-serif;
  box-shadow: inset 0 0 0 1px var(--fxv-zoom-line);

  & .fxv-zoom-head { grid-area: head; min-block-size: 40px; display: grid; align-items: center; }
  & .fxv-zoom-mhead {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    &[hidden] { display: none; }
    & h3 {
      margin: 0;
      font-size: clamp(19px, 6.4cqi, 24px);
      font-weight: 750;
      letter-spacing: -0.02em;
      & span { color: var(--fxv-zoom-dim); font-weight: 500; }
    }
    & p { margin: 0; color: var(--fxv-zoom-dim); font-variant-numeric: tabular-nums; }
  }
  & .fxv-zoom-dhead {
    display: grid;
    grid-template-columns: auto auto 1fr auto auto;
    align-items: center;
    gap: 6px;
    &[hidden] { display: none; }
  }
  & .fxv-zoom-big {
    min-inline-size: 1.15em;
    font-size: 34px;
    font-weight: 750;
    line-height: 1;
    letter-spacing: -0.03em;
    font-variant-numeric: tabular-nums;
    text-align: center;
    view-transition-class: fxv-zoom-num;
    &.is-today { color: var(--fxv-zoom-accent); }
  }
  & .fxv-zoom-dtitle {
    margin: 0;
    display: grid;
    line-height: 1.2;
    & strong { font-size: 14px; font-weight: 700; }
    & span { color: var(--fxv-zoom-dim); font-variant-numeric: tabular-nums; }
  }
  & .fxv-zoom-icon {
    all: unset;
    inline-size: 30px;
    block-size: 30px;
    display: grid;
    place-items: center;
    border-radius: 9px;
    cursor: pointer;
    color: var(--fxv-zoom-ink);
    transition: background-color 0.15s, scale 0.15s;
    & svg { inline-size: 18px; block-size: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
    &:hover { background: var(--fxv-zoom-well); }
    &:active { scale: 0.92; }
    &:focus-visible { outline: 2px solid var(--fxv-zoom-accent); outline-offset: 1px; }
  }

  & .fxv-zoom-view {
    grid-area: view;
    position: relative;
    block-size: calc(var(--fxv-zoom-hour) * 12 + 22px);
    view-transition-class: fxv-zoom-view;
  }
  & .fxv-zoom-month {
    display: grid;
    grid-template-rows: auto 1fr;
    row-gap: 4px;
    block-size: 100%;
    &[hidden] { display: none; }
  }
  & .fxv-zoom-dow {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--fxv-zoom-dim);
    text-align: center;
  }
  & .fxv-zoom-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    grid-template-rows: repeat(5, 1fr);
    gap: 3px;
  }
  & .fxv-zoom-cell {
    all: unset;
    box-sizing: border-box;
    display: grid;
    grid-template-rows: 1fr auto;
    justify-items: center;
    align-items: center;
    padding: 3px 0 5px;
    border-radius: 9px;
    font-size: 13px;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    cursor: pointer;
    transition: background-color 0.15s, scale 0.2s cubic-bezier(0.3, 1.6, 0.5, 1);
    &:hover { background: var(--fxv-zoom-well); scale: 1.06; }
    &:focus-visible { outline: 2px solid var(--fxv-zoom-ink); outline-offset: -1px; }
    &.is-out { color: color-mix(in oklch, var(--fxv-zoom-ink) 24%, var(--fxv-zoom-paper)); cursor: default; &:hover { background: none; scale: 1; } }
    &.is-weekend:not(.is-out) .fxv-zoom-n { color: var(--fxv-zoom-dim); }
  }
  & .fxv-zoom-n {
    display: grid;
    place-items: center;
    inline-size: 24px;
    block-size: 24px;
    border-radius: 50%;
    view-transition-class: fxv-zoom-num;
  }
  & .fxv-zoom-cell.is-today .fxv-zoom-n {
    position: relative;
    color: var(--fxv-zoom-paper);
    background: var(--fxv-zoom-accent);
    &::after {
      content: "";
      position: absolute;
      inset: 0;
      border-radius: 50%;
      border: 1.5px solid var(--fxv-zoom-accent);
      animation: fxv-zoom-pulse 2.6s cubic-bezier(0.2, 0.7, 0.3, 1) infinite;
    }
  }
  & .fxv-zoom-dots {
    display: flex;
    gap: 3px;
    block-size: 6px;
    & i { inline-size: 6px; block-size: 6px; border-radius: 3px; background: var(--c); view-transition-class: fxv-zoom-ev; }
  }

  & .fxv-zoom-day {
    position: relative;
    block-size: 100%;
    &[hidden] { display: none; }
  }
  & .fxv-zoom-hours {
    position: absolute;
    inset: 6px 0 0;
    margin: 0;
    padding: 0;
    list-style: none;
    & li {
      position: absolute;
      inset-inline: 0;
      top: calc(var(--h) * var(--fxv-zoom-hour) * 2);
      translate: 0 -50%;
      display: flex;
      align-items: center;
      gap: 6px;
      font: 10px/1 ui-monospace, Menlo, monospace;
      font-variant-numeric: tabular-nums;
      color: var(--fxv-zoom-dim);
      &::after { content: ""; flex: 1; border-block-start: 1px solid var(--fxv-zoom-line); }
    }
  }
  & .fxv-zoom-events {
    position: absolute;
    inset: 6px 0 0 34px;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  & .fxv-zoom-ev {
    position: absolute;
    inset-inline: 0;
    top: calc(var(--s) * var(--fxv-zoom-hour));
    block-size: max(18px, calc((var(--e) - var(--s)) * var(--fxv-zoom-hour) - 2px));
    box-sizing: border-box;
    display: flex;
    align-items: baseline;
    gap: 8px;
    padding: 3px 8px;
    overflow: hidden;
    border-radius: 6px;
    /* oklab, not oklch: mixing across distant hues in oklch swings through a
       third hue (orange + blue-black comes out purple) */
    background: color-mix(in oklab, var(--c) 17%, var(--fxv-zoom-paper));
    box-shadow: inset 3px 0 0 var(--c);
    color: color-mix(in oklab, var(--c) 50%, var(--fxv-zoom-ink));
    view-transition-class: fxv-zoom-ev;
    & b { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & time { margin-inline-start: auto; font: 10px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; opacity: 0.8; white-space: nowrap; }
  }
  & .fxv-zoom-now {
    position: absolute;
    inset-inline: 30px 0;
    top: calc(6px + var(--t) * var(--fxv-zoom-hour));
    block-size: 0;
    border-block-start: 1.5px solid var(--fxv-zoom-accent);
    &::before { content: ""; position: absolute; inset-inline-start: -4px; top: -4.5px; inline-size: 7px; block-size: 7px; border-radius: 50%; background: var(--fxv-zoom-accent); }
  }
  & .fxv-zoom-free {
    position: absolute;
    inset: 40% 0 auto 34px;
    margin: 0;
    text-align: center;
    color: var(--fxv-zoom-dim);
    text-wrap: balance;
  }
  & .fxv-zoom-day:has(.fxv-zoom-ev) .fxv-zoom-free { display: none; }

  & .fxv-zoom-legend {
    grid-area: legend;
    display: flex;
    gap: 14px;
    padding-block-start: 8px;
    border-block-start: 1px solid var(--fxv-zoom-line);
    font-size: 11px;
    color: var(--fxv-zoom-dim);
    & span { display: inline-flex; align-items: center; gap: 5px; }
    & span::before { content: ""; inline-size: 7px; block-size: 7px; border-radius: 2px; background: var(--c); }
  }
}

@container (inline-size < 290px) {
  .fxv-zoom .fxv-zoom-ev time { display: none; }
  .fxv-zoom .fxv-zoom-cell { font-size: 12px; }
}

/* The zoom itself is scripted per direction (the origin is the clicked day);
   CSS only sets the shared timing and keeps the view's group clipped so the
   magnified month never spills past its own frame. */
::view-transition-group(.fxv-zoom-view) {
  overflow: clip;
  border-radius: 10px;
  animation-duration: 0.56s;
}
::view-transition-group(.fxv-zoom-num),
::view-transition-group(.fxv-zoom-ev) {
  animation-duration: 0.56s;
  animation-timing-function: cubic-bezier(0.55, 0, 0.12, 1);
}
/* dot <-> block: the group is painted in the event colour by the script and
   rounds the corners; the dot's snapshot leaves early, the block's arrives late */
::view-transition-group(.fxv-zoom-ev) { border-radius: 5px; }
::view-transition-old(.fxv-zoom-ev),
::view-transition-new(.fxv-zoom-ev) {
  inline-size: 100%;
  block-size: 100%;
  object-fit: fill;
}
::view-transition-old(.fxv-zoom-ev) { animation: fxv-zoom-fade-out 0.22s ease-in both; }
::view-transition-new(.fxv-zoom-ev) { animation: fxv-zoom-fade-in 0.3s 0.2s ease-out both; }
::view-transition-group(.fxv-zoom-root) { animation-duration: 0.34s; }

@keyframes fxv-zoom-fade-in { from { opacity: 0; } }
@keyframes fxv-zoom-fade-out { to { opacity: 0; } }
@keyframes fxv-zoom-pulse {
  0% { transform: scale(1); opacity: 0.7; }
  70%, 100% { transform: scale(1.55); opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .fxv-zoom .fxv-zoom-cell.is-today .fxv-zoom-n::after { animation: none; opacity: 0; }
  .fxv-zoom .fxv-zoom-cell, .fxv-zoom .fxv-zoom-icon { transition: none; }
  .fxv-zoom .fxv-zoom-cell:hover { scale: 1; }
  ::view-transition-group(.fxv-zoom-view), ::view-transition-group(.fxv-zoom-root) { animation-duration: 0.2s; }
}

js:
/* ── view-transition plumbing ─────────────────────────────────────────
   1. root.startViewTransition()     scoped: snapshots only this component, clips
                                      to it, and leaves the rest of the page live
   2. document.startViewTransition() whole-document snapshot; the root is named
                                      for the duration so it animates as one group
   3. FLIP with the Web Animations API when neither exists
   Names carry a per-instance id so two copies on one page never collide.  */
const ID = 'fxv-zoom';
const UID = Math.random().toString(36).slice(2, 8);
const ROOT_NAME = ID + '-' + UID;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SCOPED = typeof root.startViewTransition === 'function';
const DOCVT = typeof document.startViewTransition === 'function';
const vtName = key => ROOT_NAME + '-' + key;
const host = () => (SCOPED ? root : document.documentElement);
let running = null;

function nameParts(on) {
  root.querySelectorAll('[data-vt]').forEach(el => {
    el.style.viewTransitionName = on && !RM.matches && el.getClientRects().length ? vtName(el.dataset.vt) : '';
  });
}

function morph(update, onReady, onAbort) {
  if (!SCOPED && !DOCVT) { flip(update); return null; }
  const first = measure();
  nameParts(true);
  root.style.viewTransitionName = ROOT_NAME;
  const run = () => { update(); nameParts(true); };
  const t = SCOPED ? root.startViewTransition(run) : document.startViewTransition(run);
  running = t;
  t.ready.then(() => { if (onReady && !RM.matches) onReady(t); }, e => {
    /* An AbortError just means a newer transition took over. Chrome can also
       abort a scoped transition with InvalidStateError while others run on
       the page; the DOM still updates, so replay the change instead of letting
       it snap: FLIP from the geometry measured above, or the caller's own. */
    if (!e || e.name !== 'InvalidStateError' || RM.matches) return;
    t.updateCallbackDone.then(() => (onAbort ? onAbort() : play(first)), () => {});
  });
  t.finished.finally(() => {
    if (running !== t) return;
    running = null;
    nameParts(false);
    root.style.viewTransitionName = '';
  });
  return t;
}

/* Animate one of this transition's pseudo-elements from script. */
function pseudo(part, key, keyframes, opts) {
  const name = key === 'root' ? ROOT_NAME : vtName(key);
  return host().animate(keyframes, Object.assign({ fill: 'both' }, opts, { pseudoElement: '::view-transition-' + part + '(' + name + ')' }));
}

/* All running animations that belong to one of our named groups. */
function ownAnimations() {
  return host().getAnimations({ subtree: true }).filter(a => {
    const p = a.effect && a.effect.pseudoElement;
    return p && p.indexOf(ROOT_NAME + '-') > -1;
  });
}

const measure = () => null;
const play = () => {};
function flip(update) { update(); }

/* One source of truth: every count, dot and block is derived from EVENTS. */
const EVENTS = [
  [1, '10:00', '12:00', 'Glaze trials', 'studio'],
  [2, '09:00', '10:30', 'Kiln unload', 'studio'],
  [2, '13:00', '15:00', "Beginners' wheel", 'class'],
  [2, '18:30', '20:00', 'Supper with Corran', 'personal'],
  [5, '10:00', '13:00', 'Throwing: dinner set', 'studio'],
  [6, '18:00', '20:00', 'Evening wheel class', 'class'],
  [8, '09:30', '10:30', 'Clay delivery', 'studio'],
  [8, '14:00', '16:00', "Kids' hand-building", 'class'],
  [10, '08:15', '09:05', 'Ferry to Kesh Isle', 'personal'],
  [10, '10:00', '17:00', 'Craft fair stall', 'studio'],
  [13, '18:00', '20:00', 'Evening wheel class', 'class'],
  [15, '08:30', '10:00', 'Bisque firing', 'studio'],
  [15, '12:00', '12:40', 'Dentist', 'personal'],
  [20, '18:00', '20:00', 'Evening wheel class', 'class'],
  [21, '11:00', '11:30', 'Glaze order arrives', 'studio'],
  [23, '17:00', '20:00', 'Open studio evening', 'studio'],
  [27, '18:00', '20:00', 'Evening wheel class', 'class'],
  [31, '09:00', '12:00', 'Kiln maintenance', 'studio']
].map((e, i) => ({ id: 'e' + i, day: e[0], from: e[1], to: e[2], title: e[3], cat: e[4] }));
const TODAY = 2, DAYS = 31, START = 8;
const LEAD = (new Date(2026, 9, 1).getDay() + 6) % 7;      /* Monday-first */
const WEEKDAY = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const hrs = t => { const [h, m] = t.split(':'); return +h + m / 60 - START; };
const onDay = d => EVENTS.filter(e => e.day === d);
const plural = n => n + (n === 1 ? ' event' : ' events');

const $ = s => root.querySelector(s);
const view = $('.fxv-zoom-view'), monthEl = $('.fxv-zoom-month'), dayEl = $('.fxv-zoom-day');
const grid = $('.fxv-zoom-grid'), list = $('.fxv-zoom-events');
const mhead = $('.fxv-zoom-mhead'), dhead = $('.fxv-zoom-dhead'), big = $('.fxv-zoom-big');
let mode = 'month', day = TODAY, focus = TODAY;

$('.fxv-zoom-total').textContent = plural(EVENTS.length);
$('.fxv-zoom-hours').innerHTML = [0, 1, 2, 3, 4, 5, 6].map(h => '<li style="--h:' + h + '">' + String(START + h * 2).padStart(2, '0') + '</li>').join('');

let cells = '';
for (let i = 0; i < 35; i++) {
  const d = i - LEAD + 1, wk = i % 7 > 4 ? ' is-weekend' : '';
  if (d < 1 || d > DAYS) {
    cells += '<span class="fxv-zoom-cell is-out' + wk + '" aria-hidden="true"><span class="fxv-zoom-n">' + (d < 1 ? 30 + d : d - DAYS) + '</span><span class="fxv-zoom-dots"></span></span>';
    continue;
  }
  const ev = onDay(d);
  cells += '<button type="button" class="fxv-zoom-cell' + wk + (d === TODAY ? ' is-today' : '') + '" data-day="' + d + '" tabindex="' + (d === TODAY ? 0 : -1) + '"' +
    ' aria-label="' + WEEKDAY[i % 7] + ' ' + d + ' October, ' + (ev.length ? plural(ev.length) : 'nothing booked') + '">' +
    '<span class="fxv-zoom-n">' + d + '</span><span class="fxv-zoom-dots">' +
    ev.map(e => '<i data-ev="' + e.id + '" style="--c:var(--fxv-zoom-' + e.cat + ')"></i>').join('') + '</span></button>';
}
grid.innerHTML = cells;
const cellOf = d => grid.querySelector('[data-day="' + d + '"]');

/* Only the focused day's number and dots carry data-vt, so only they fly;
   everything else rides inside the view's own snapshot and zooms with it. */
function tagFocus(named) {
  root.querySelectorAll('[data-vt]:not(.fxv-zoom-view)').forEach(el => {
    el.removeAttribute('data-vt');
    el.style.viewTransitionName = '';
  });
  if (!named) return;
  const c = cellOf(focus);
  if (mode === 'month') {
    c.querySelector('.fxv-zoom-n').dataset.vt = 'n' + focus;
    c.querySelectorAll('[data-ev]').forEach(i => (i.dataset.vt = i.dataset.ev));
  } else {
    big.dataset.vt = 'n' + day;
    list.querySelectorAll('[data-ev]').forEach(li => (li.dataset.vt = li.dataset.ev));
  }
}

function render(named = true) {
  monthEl.hidden = mode !== 'month';
  dayEl.hidden = mode !== 'day';
  mhead.hidden = mode !== 'month';
  dhead.hidden = mode !== 'day';
  root.dataset.mode = mode;
  if (mode === 'day') {
    const ev = onDay(day), dow = (LEAD + day - 1) % 7;
    big.textContent = day;
    big.classList.toggle('is-today', day === TODAY);
    dhead.querySelector('strong').textContent = WEEKDAY[dow] + (day === TODAY ? ', today' : '');
    dhead.querySelector('span').textContent = ev.length ? plural(ev.length) : 'Free day';
    dhead.querySelector('[data-act="prev"]').disabled = day === 1;
    dhead.querySelector('[data-act="next"]').disabled = day === DAYS;
    list.innerHTML = ev.map(e =>
      '<li class="fxv-zoom-ev" data-ev="' + e.id + '" style="--s:' + hrs(e.from) + ';--e:' + hrs(e.to) + ';--c:var(--fxv-zoom-' + e.cat + ')">' +
      '<b>' + e.title + '</b><time>' + e.from + '–' + e.to + '</time></li>').join('');
    const old = dayEl.querySelector('.fxv-zoom-now');
    if (old) old.remove();
    if (day === TODAY) {
      const n = new Date(), t = n.getHours() + n.getMinutes() / 60 - START;
      if (t > 0 && t < 12) dayEl.insertAdjacentHTML('beforeend', '<span class="fxv-zoom-now" style="--t:' + t.toFixed(3) + '" aria-hidden="true"></span>');
    }
  }
  tagFocus(named);
}

/* the clicked day's centre, in the view's own box: the zoom's transform-origin */
function origin(d) {
  const v = view.getBoundingClientRect(), c = cellOf(d).getBoundingClientRect();
  return (c.left + c.width / 2 - v.left).toFixed(1) + 'px ' + (c.top + c.height / 2 - v.top).toFixed(1) + 'px';
}

const EASE = 'cubic-bezier(.55,0,.12,1)';
function paintEvents(toBlock) {
  /* each dot becomes a block: the group itself is painted, from the dot's full
     colour to the block's tint, while the block's own snapshot fades in over it.
     Colours are resolved here because the pseudo-elements of a document-level
     transition hang off <html> and cannot see this component's variables. */
  const cs = getComputedStyle(root), paper = cs.getPropertyValue('--fxv-zoom-paper').trim();
  EVENTS.filter(e => e.day === focus).forEach(e => {
    const c = cs.getPropertyValue('--fxv-zoom-' + e.cat).trim();
    const tint = 'color-mix(in oklab, ' + c + ' 17%, ' + paper + ')';
    pseudo('group', e.id, { backgroundColor: toBlock ? [c, c, tint] : [tint, c, c] }, { duration: 560, easing: 'linear' });
  });
}

const back = dhead.querySelector('[data-act="out"]');
function zoomIn(d) {
  if (mode === 'day') return;
  focus = d;
  tagFocus(true);
  const o = origin(d);
  if (!SCOPED && !DOCVT) { mode = 'day'; day = d; render(); back.focus({ preventScroll: true }); fallback(o, 0.6); return; }
  morph(() => { mode = 'day'; day = d; render(); back.focus({ preventScroll: true }); }, () => {
    pseudo('old', 'view', [{ transform: 'scale(1)', opacity: 1, transformOrigin: o }, { opacity: 0, offset: 0.55 }, { transform: 'scale(2.8)', opacity: 0, transformOrigin: o }], { duration: 560, easing: EASE });
    pseudo('new', 'view', [{ transform: 'scale(.34)', opacity: 0, transformOrigin: o }, { opacity: 0, offset: 0.18 }, { opacity: 1, offset: 0.7 }, { transform: 'scale(1)', opacity: 1, transformOrigin: o }], { duration: 560, easing: EASE });
    paintEvents(true);
  }, () => fallback(o, 0.6));
}

function rest() {
  grid.querySelectorAll('[data-day]').forEach(b => (b.tabIndex = +b.dataset.day === focus ? 0 : -1));
  cellOf(focus).focus({ preventScroll: true });
}
function zoomOut() {
  if (mode === 'month') return;
  focus = day;
  tagFocus(true);
  if (!SCOPED && !DOCVT) { mode = 'month'; render(); rest(); fallback(origin(focus), 1.6); return; }
  let o = '50% 50%';
  morph(() => { mode = 'month'; render(); rest(); o = origin(focus); }, () => {
    pseudo('old', 'view', [{ transform: 'scale(1)', opacity: 1, transformOrigin: o }, { opacity: 0, offset: 0.5 }, { transform: 'scale(.34)', opacity: 0, transformOrigin: o }], { duration: 560, easing: EASE });
    pseudo('new', 'view', [{ transform: 'scale(2.8)', opacity: 0, transformOrigin: o }, { opacity: 1, offset: 0.62 }, { transform: 'scale(1)', opacity: 1, transformOrigin: o }], { duration: 560, easing: EASE });
    paintEvents(false);
  }, () => fallback(o, 1.6));
}

function step(dir) {
  const d = day + dir;
  if (mode !== 'day' || d < 1 || d > DAYS) return;
  focus = d;
  /* no named parts here: blocks and date ride inside the sliding view */
  tagFocus(false);
  if (!SCOPED && !DOCVT) { day = d; render(false); return; }
  morph(() => { day = d; render(false); }, () => {
    const t = { duration: 380, easing: 'cubic-bezier(.3,.8,.2,1)' };
    pseudo('old', 'view', { transform: ['translateX(0)', 'translateX(' + (-dir * 36) + 'px)'], opacity: [1, 0] }, t);
    pseudo('new', 'view', { transform: ['translateX(' + (dir * 36) + 'px)', 'translateX(0)'], opacity: [0, 1] }, t);
  });
}

/* without view transitions: scale the incoming view out of (or back into) the day */
function fallback(o, from) {
  if (RM.matches) return;
  view.animate([{ transform: 'scale(' + from + ')', opacity: 0, transformOrigin: o }, { transform: 'none', opacity: 1, transformOrigin: o }],
    { duration: 420, easing: 'cubic-bezier(.2,.8,.2,1)' });
}

root.addEventListener('click', e => {
  const c = e.target.closest('.fxv-zoom-cell[data-day]');
  if (c) { zoomIn(+c.dataset.day); return; }
  const a = e.target.closest('[data-act]');
  if (!a) return;
  if (a.dataset.act === 'out') zoomOut();
  else step(a.dataset.act === 'next' ? 1 : -1);
});

root.addEventListener('keydown', e => {
  if (mode === 'day') {
    if (e.key === 'Escape') { e.preventDefault(); zoomOut(); }
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') { e.preventDefault(); step(e.key === 'ArrowRight' ? 1 : -1); }
    return;
  }
  const c = document.activeElement.closest && document.activeElement.closest('.fxv-zoom-cell[data-day]');
  if (!c) return;
  const delta = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 }[e.key];
  if (!delta) return;
  e.preventDefault();
  const n = cellOf(Math.min(DAYS, Math.max(1, +c.dataset.day + delta)));
  c.tabIndex = -1;
  n.tabIndex = 0;
  n.focus();
});

render();

css:
.fxv-forecast {
  --fxv-forecast-bg: oklch(0.255 0.022 248);
  --fxv-forecast-ink: oklch(0.96 0.01 240);
  --fxv-forecast-sun: oklch(0.83 0.15 78);
  --fxv-forecast-rain: oklch(0.74 0.11 236);
  --fxv-forecast-cloud: color-mix(in oklch, var(--fxv-forecast-ink) 78%, var(--fxv-forecast-bg));
  --fxv-forecast-dim: color-mix(in oklch, var(--fxv-forecast-ink) 58%, var(--fxv-forecast-bg));
  --fxv-forecast-line: color-mix(in oklch, var(--fxv-forecast-ink) 12%, transparent);
  --fxv-forecast-well: color-mix(in oklch, var(--fxv-forecast-ink) 6%, var(--fxv-forecast-bg));

  container-type: inline-size;
  view-transition-class: fxv-forecast-root;
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  inline-size: 100%;
  max-inline-size: 460px;
  display: grid;
  grid-template-areas: "head" "tabs" "panel";
  row-gap: 12px;
  padding: 16px;
  border-radius: 20px;
  color: var(--fxv-forecast-ink);
  font: 12.5px/1.35 system-ui, sans-serif;
  background:
    radial-gradient(90% 70% at 85% 0%, color-mix(in oklch, var(--fxv-forecast-sun) 16%, transparent), transparent 70%),
    var(--fxv-forecast-bg);
  box-shadow: inset 0 0 0 1px var(--fxv-forecast-line);

  & .fxv-forecast-head {
    grid-area: head;
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 8px;
    & h3 { margin: 0; font-size: 15px; font-weight: 700; letter-spacing: -0.005em; }
    & p { margin: 0; color: var(--fxv-forecast-dim); font-size: 11.5px; font-variant-numeric: tabular-nums; white-space: nowrap; }
  }

  & .fxv-forecast-tabs {
    grid-area: tabs;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    padding: 3px;
    border-radius: 11px;
    background: var(--fxv-forecast-well);
    & button {
      all: unset;
      grid-row: 1;
      padding: 6px 0;
      border-radius: 8px;
      text-align: center;
      font-weight: 600;
      color: var(--fxv-forecast-dim);
      cursor: pointer;
      view-transition-class: fxv-forecast-tab;
      &:hover { color: var(--fxv-forecast-ink); }
      &[aria-selected="true"] { color: var(--fxv-forecast-bg); }
      &:focus-visible { outline: 2px solid var(--fxv-forecast-sun); outline-offset: 1px; }
    }
  }
  & .fxv-forecast-pill {
    grid-row: 1;
    grid-column: var(--fxv-forecast-at, 1);
    border-radius: 8px;
    background: var(--fxv-forecast-ink);
    view-transition-class: fxv-forecast-pill;
  }

  & .fxv-forecast-panel {
    grid-area: panel;
    position: relative;
    block-size: 208px;
  }

  /* ── shared atoms ── */
  & .fxv-forecast-ico {
    display: block;
    fill: none;
    stroke-width: 1.6;
    stroke-linecap: round;
    stroke-linejoin: round;
    overflow: visible;
    view-transition-class: fxv-forecast-morph;
    & .sun { stroke: var(--fxv-forecast-sun); }
    & .sun circle { fill: color-mix(in oklch, var(--fxv-forecast-sun) 30%, transparent); }
    & .rays { transform-origin: 12px 12px; animation: fxv-forecast-spin 30s linear infinite; }
    & .cloud { stroke: var(--fxv-forecast-cloud); fill: var(--fxv-forecast-bg); animation: fxv-forecast-drift 5s ease-in-out infinite alternate; }
    /* transform + opacity only: a paint-only animation (stroke-dashoffset) inside
       the scope makes Chrome abort the first element-scoped transition */
    & .drops { stroke: var(--fxv-forecast-rain); animation: fxv-forecast-rain 1.1s cubic-bezier(0.5, 0, 1, 1) infinite; }
  }
  & .fxv-forecast-range {
    position: relative;
    block-size: 6px;
    border-radius: 3px;
    background: var(--fxv-forecast-line);
    view-transition-class: fxv-forecast-morph;
    & i {
      position: absolute;
      inset-block: 0;
      left: var(--a);
      right: calc(100% - var(--b));
      border-radius: 3px;
      background: linear-gradient(90deg, var(--fxv-forecast-rain), var(--fxv-forecast-sun));
    }
    & b {
      position: absolute;
      top: 50%;
      left: var(--n);
      inline-size: 10px;
      block-size: 10px;
      margin: -5px 0 0 -5px;
      border-radius: 50%;
      background: var(--fxv-forecast-ink);
      box-shadow: 0 0 0 2px var(--fxv-forecast-bg);
    }
  }
  & .fxv-forecast-temp {
    font-variant-numeric: tabular-nums;
    font-weight: 600;
    view-transition-class: fxv-forecast-morph;
  }
  & [data-i] { view-transition-class: fxv-forecast-item; }

  /* ── Now ── */
  & .fxv-forecast-now {
    display: grid;
    grid-template-columns: auto 1fr;
    grid-template-areas: "ico big" "range range" "stats stats" "note note";
    column-gap: 14px;
    row-gap: 14px;
    align-items: center;
    & > .fxv-forecast-ico { grid-area: ico; inline-size: 68px; block-size: 68px; }
    & .fxv-forecast-big { grid-area: big; display: grid; gap: 2px; }
    & .fxv-forecast-temp { font-size: clamp(46px, 17cqi, 60px); font-weight: 300; line-height: 0.9; letter-spacing: -0.04em; justify-self: start; }
    & .fxv-forecast-big p { margin: 0; color: var(--fxv-forecast-dim); }
    & .fxv-forecast-big p strong { color: var(--fxv-forecast-ink); font-weight: 600; }
    & .fxv-forecast-rangewrap { grid-area: range; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; font-variant-numeric: tabular-nums; color: var(--fxv-forecast-dim); }
    & .fxv-forecast-stats { grid-area: stats; display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin: 0; }
    & .fxv-forecast-stats div { padding: 8px 10px; border-radius: 10px; background: var(--fxv-forecast-well); }
    & dt { font-size: 9.5px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--fxv-forecast-dim); }
    & dd { margin: 2px 0 0; font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
    & .fxv-forecast-note {
      grid-area: note;
      display: flex;
      align-items: center;
      gap: 8px;
      margin: 0;
      color: var(--fxv-forecast-dim);
      text-wrap: pretty;
      & .fxv-forecast-ico { inline-size: 20px; block-size: 20px; flex: none; }
    }
  }

  /* ── Hourly ── */
  & .fxv-forecast-hours {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    grid-template-rows: auto 60px auto auto;
    row-gap: 8px;
    padding-block-start: 6px;
    & .fxv-forecast-curve { grid-row: 2; grid-column: 1 / -1; inline-size: 100%; block-size: 60px; overflow: visible; }
    & .fxv-forecast-curve path { fill: none; stroke: var(--fxv-forecast-sun); stroke-width: 2; vector-effect: non-scaling-stroke; }
    & .fxv-forecast-curve path + path { stroke: none; fill: color-mix(in oklch, var(--fxv-forecast-sun) 12%, transparent); }
    & .fxv-forecast-curve circle { fill: var(--fxv-forecast-bg); stroke: var(--fxv-forecast-sun); stroke-width: 2; vector-effect: non-scaling-stroke; }
  }
  & .fxv-forecast-slot { display: contents; }
  & .fxv-forecast-hl { grid-row: 1; text-align: center; color: var(--fxv-forecast-dim); font-size: 11px; font-variant-numeric: tabular-nums; }
  & .fxv-forecast-hl.is-now { color: var(--fxv-forecast-ink); font-weight: 700; }
  & .fxv-forecast-hi { grid-row: 3; justify-self: center; inline-size: 24px; block-size: 24px; }
  & .fxv-forecast-ht { grid-row: 4; justify-self: center; font-size: 14px; }
  & .fxv-forecast-pop {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    margin-block-start: 6px;
    padding-block-start: 8px;
    border-block-start: 1px solid var(--fxv-forecast-line);
    font: 10.5px ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    text-align: center;
    color: var(--fxv-forecast-rain);
  }

  /* ── 5-day ── */
  & .fxv-forecast-week { display: grid; row-gap: 4px; margin: 0; padding: 0; list-style: none; }
  & .fxv-forecast-row {
    display: grid;
    grid-template-columns: 3.4em 24px 3em 2.2em 1fr 2.2em;
    align-items: center;
    column-gap: 8px;
    block-size: 38px;
    padding-inline: 8px;
    border-radius: 10px;
    &:first-child { background: var(--fxv-forecast-well); }
    & > span:first-child { font-weight: 600; }
    & .fxv-forecast-ico { inline-size: 22px; block-size: 22px; }
    & .p { color: var(--fxv-forecast-rain); font: 10.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
    & .lo { color: var(--fxv-forecast-dim); text-align: end; font-variant-numeric: tabular-nums; }
    & .hi { font-weight: 600; font-variant-numeric: tabular-nums; }
  }
}

@container (inline-size < 290px) {
  .fxv-forecast .fxv-forecast-upd { display: none; }
  .fxv-forecast .fxv-forecast-row { grid-template-columns: 3em 22px 2em 1fr 2em; }
  .fxv-forecast .fxv-forecast-row .p { display: none; }
  .fxv-forecast .fxv-forecast-now dd { font-size: 11.5px; }
}

/* Shared readings (icon, temperature, range bar, the tab pill) morph on a
   spring. Everything else enters and leaves on its own: new-only snapshots
   rise in, staggered from script by data-i; old-only ones just fade. */
::view-transition-group(.fxv-forecast-morph),
::view-transition-group(.fxv-forecast-pill) {
  animation-duration: 0.56s;
  animation-timing-function: linear(0, 0.026, 0.091, 0.181, 0.285, 0.393, 0.499, 0.598, 0.688, 0.766, 0.833, 0.889, 0.933, 0.968, 0.995, 1.013, 1.026, 1.034, 1.038, 1.038, 1.037, 1.034, 1.031, 1.027, 1.023, 1.019, 1.015, 1.012, 1.009, 1.006, 1);
}
::view-transition-group(.fxv-forecast-item) { animation-duration: 0.42s; }
::view-transition-new(.fxv-forecast-item):only-child {
  animation: fxv-forecast-in 0.42s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
::view-transition-old(.fxv-forecast-item):only-child {
  animation: fxv-forecast-out 0.16s ease-in both;
}
::view-transition-group(.fxv-forecast-tab) { animation-duration: 0.3s; }
::view-transition-group(.fxv-forecast-root) { animation-duration: 0.3s; }

@keyframes fxv-forecast-in { from { opacity: 0; transform: translateY(10px) scale(0.96); } }
@keyframes fxv-forecast-out { to { opacity: 0; } }
@keyframes fxv-forecast-spin { to { transform: rotate(360deg); } }
@keyframes fxv-forecast-drift { from { transform: translateX(-0.6px); } to { transform: translateX(1.2px); } }
@keyframes fxv-forecast-rain {
  0% { transform: translateY(-2px); opacity: 0; }
  30% { opacity: 1; }
  100% { transform: translateY(2.5px); opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .fxv-forecast .fxv-forecast-ico :is(.rays, .cloud, .drops) { animation: none; }
  ::view-transition-new(.fxv-forecast-item):only-child { animation: fxv-forecast-fade 0.2s ease both; }
  ::view-transition-group(.fxv-forecast-root) { animation-duration: 0.2s; }
}
@keyframes fxv-forecast-fade { from { opacity: 0; } }

