/* ── view-transition plumbing ─────────────────────────────────────────
   1. root.startViewTransition()     scoped: snapshots only this component, clips
                                      to it, and leaves the rest of the page live
   2. document.startViewTransition() whole-document snapshot; the root is named
                                      for the duration so it animates as one group
   3. FLIP with the Web Animations API when neither exists
   Names carry a per-instance id so two copies on one page never collide.  */
const ID = 'fxv-forecast';
const UID = Math.random().toString(36).slice(2, 8);
const ROOT_NAME = ID + '-' + UID;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SCOPED = typeof root.startViewTransition === 'function';
const DOCVT = typeof document.startViewTransition === 'function';
const vtName = key => ROOT_NAME + '-' + key;
const host = () => (SCOPED ? root : document.documentElement);
let running = null;

function nameParts(on) {
  root.querySelectorAll('[data-vt]').forEach(el => {
    el.style.viewTransitionName = on && !RM.matches && el.getClientRects().length ? vtName(el.dataset.vt) : '';
  });
}

function morph(update, onReady, onAbort) {
  if (!SCOPED && !DOCVT) { flip(update); return null; }
  const first = measure();
  nameParts(true);
  root.style.viewTransitionName = ROOT_NAME;
  const run = () => { update(); nameParts(true); };
  const t = SCOPED ? root.startViewTransition(run) : document.startViewTransition(run);
  running = t;
  t.ready.then(() => { if (onReady && !RM.matches) onReady(t); }, e => {
    /* An AbortError just means a newer transition took over. Chrome can also
       abort a scoped transition with InvalidStateError while others run on
       the page; the DOM still updates, so replay the change instead of letting
       it snap: FLIP from the geometry measured above, or the caller's own. */
    if (!e || e.name !== 'InvalidStateError' || RM.matches) return;
    t.updateCallbackDone.then(() => (onAbort ? onAbort() : play(first)), () => {});
  });
  t.finished.finally(() => {
    if (running !== t) return;
    running = null;
    nameParts(false);
    root.style.viewTransitionName = '';
  });
  return t;
}

/* Animate one of this transition's pseudo-elements from script. */
function pseudo(part, key, keyframes, opts) {
  const name = key === 'root' ? ROOT_NAME : vtName(key);
  return host().animate(keyframes, Object.assign({ fill: 'both' }, opts, { pseudoElement: '::view-transition-' + part + '(' + name + ')' }));
}

/* All running animations that belong to one of our named groups. */
function ownAnimations() {
  return host().getAnimations({ subtree: true }).filter(a => {
    const p = a.effect && a.effect.pseudoElement;
    return p && p.indexOf(ROOT_NAME + '-') > -1;
  });
}

/* FLIP: first rects of every outermost [data-vt] element, then invert + play */
const outermost = el => { const p = el.parentElement.closest('[data-vt]'); return !p || !root.contains(p); };
function measure() {
  const m = new Map();
  if (RM.matches) return m;
  root.querySelectorAll('[data-vt]').forEach(el => {
    if (outermost(el) && el.getClientRects().length) m.set(el.dataset.vt, el.getBoundingClientRect());
  });
  return m;
}
function play(first) {
  if (RM.matches || !first) return;
  root.querySelectorAll('[data-vt]').forEach(el => {
    if (!outermost(el)) return;
    const b = el.getBoundingClientRect();
    if (!b.width) return;
    const a = first.get(el.dataset.vt);
    if (!a) {
      el.animate({ opacity: [0, 1], transform: ['scale(.94)', 'none'] }, { duration: 320, easing: 'cubic-bezier(.2,.8,.2,1)', fill: 'backwards' });
      return;
    }
    const dx = a.left - b.left, dy = a.top - b.top, sx = a.width / b.width, sy = a.height / b.height;
    if (Math.abs(dx) + Math.abs(dy) < 1 && Math.abs(sx - 1) + Math.abs(sy - 1) < 0.01) return;
    el.animate({
      transformOrigin: ['0 0', '0 0'],
      transform: ['translate(' + dx + 'px,' + dy + 'px) scale(' + sx + ',' + sy + ')', 'none']
    }, { duration: 520, easing: 'cubic-bezier(.2,.9,.25,1)' });
  });
}
function flip(update) {
  const first = measure();
  update();
  play(first);
}

/* Readings for Port Ellery, Fri 2 Oct at 14:00. Today's high is the hourly
   peak and the 5-day scale spans the week's own extremes. */
const NOW = { t: 17, sky: 'partly', label: 'Bright spells', feels: 15, wind: '18 km/h SW', hum: 64, pop: 10 };
const HOURS = [['Now', 17, 'partly', 10], ['15:00', 18, 'sun', 0], ['16:00', 19, 'sun', 0], ['17:00', 18, 'partly', 5], ['18:00', 16, 'cloud', 20], ['19:00', 14, 'rain', 40]];
const WEEK = [['Today', 'partly', 10, 11, 19], ['Sat', 'rain', 80, 9, 15], ['Sun', 'cloud', 30, 8, 14], ['Mon', 'sun', 0, 9, 17], ['Tue', 'partly', 10, 10, 18]];
const LO = Math.min(...WEEK.map(d => d[3])), HI = Math.max(...WEEK.map(d => d[4]));
const pct = v => ((v - LO) / (HI - LO) * 100).toFixed(1) + '%';

function icon(kind, vt) {
  const sun = '<g class="sun"><circle cx="12" cy="12" r="4"/><path class="rays" d="M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6l1.4 1.4M17 17l1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4"/></g>';
  const small = '<g class="sun"><circle cx="9" cy="9" r="3.2"/><path class="rays" style="transform-origin:9px 9px" d="M9 2.5v1.5M2.5 9H4M4.4 4.4l1 1M13.6 4.4l-1 1"/></g>';
  const cloud = (x) => '<path class="cloud" d="M' + (7 + x) + ' 19h9.5a3.5 3.5 0 0 0 .3-7A5 5 0 0 0 ' + (7.4 + x) + ' 11.2 4 4 0 0 0 ' + (7 + x) + ' 19Z"/>';
  const body = kind === 'sun' ? sun
    : kind === 'partly' ? small + cloud(1)
    : kind === 'cloud' ? cloud(0)
    : '<path class="drops" d="M9 20v2.2M13 20.8v2.2M17 20v2.2"/>' + cloud(0).replace('19h', '17.5h').replace(' 19Z', ' 17.5Z');
  return '<svg class="fxv-forecast-ico" viewBox="0 0 24 24" aria-hidden="true"' + (vt ? ' data-vt="' + vt + '"' : '') + '>' + body + '</svg>';
}
const range = (lo, hi, vt, now) => '<span class="fxv-forecast-range" data-vt="' + vt + '" style="--a:' + pct(lo) + ';--b:' + pct(hi) + (now != null ? ';--n:' + pct(now) : '') + '"><i></i>' + (now != null ? '<b></b>' : '') + '</span>';

const VIEWS = {
  now: () =>
    '<div class="fxv-forecast-now">' + icon(NOW.sky, 'icon') +
    '<div class="fxv-forecast-big"><span class="fxv-forecast-temp" data-vt="temp">' + NOW.t + '°</span>' +
    '<p data-vt="cond" data-i="1"><strong>' + NOW.label + '</strong> · feels ' + NOW.feels + '°</p></div>' +
    '<div class="fxv-forecast-rangewrap"><span data-vt="lo" data-i="2">L ' + WEEK[0][3] + '°</span>' + range(WEEK[0][3], WEEK[0][4], 'range', NOW.t) + '<span data-vt="hi" data-i="2">H ' + WEEK[0][4] + '°</span></div>' +
    '<dl class="fxv-forecast-stats">' +
    [['Wind', NOW.wind], ['Humidity', NOW.hum + '%'], ['Rain', NOW.pop + '%']].map((s, i) => '<div data-vt="s' + i + '" data-i="' + (3 + i) + '"><dt>' + s[0] + '</dt><dd>' + s[1] + '</dd></div>').join('') +
    '</dl><p class="fxv-forecast-note" data-vt="note" data-i="6">' + icon('rain') + 'Showers from ' + HOURS[5][0] + ', ' + HOURS[5][3] + '% chance; heavier on Saturday.</p></div>',
  hours: () => {
    const xs = HOURS.map((h, i) => (i + 0.5) / HOURS.length * 100), lo = Math.min(...HOURS.map(h => h[1])), hi = Math.max(...HOURS.map(h => h[1]));
    const ys = HOURS.map(h => 50 - (h[1] - lo) / (hi - lo) * 40);
    const line = xs.map((x, i) => (i ? 'L' : 'M') + x.toFixed(2) + ' ' + ys[i].toFixed(1)).join(' ');
    return '<div class="fxv-forecast-hours">' +
      HOURS.map((h, i) => '<span class="fxv-forecast-hl' + (i ? '' : ' is-now') + '" data-vt="hl' + i + '" data-i="' + i + '">' + h[0] + '</span>').join('') +
      '<svg class="fxv-forecast-curve" data-vt="curve" data-i="1" viewBox="0 0 100 60" preserveAspectRatio="none" aria-hidden="true"><path d="' + line + '"/><path d="' + line + ' L' + xs[5].toFixed(2) + ' 60 L' + xs[0].toFixed(2) + ' 60Z"/></svg>' +
      HOURS.map((h, i) => icon(h[2], i ? 'hi' + i : 'icon').replace('class="fxv-forecast-ico"', 'class="fxv-forecast-ico fxv-forecast-hi"' + (i ? ' data-i="' + i + '"' : '') + ' style="grid-column:' + (i + 1) + '"')).join('') +
      HOURS.map((h, i) => '<span class="fxv-forecast-temp fxv-forecast-ht" style="grid-column:' + (i + 1) + '" data-vt="' + (i ? 'ht' + i : 'temp') + '"' + (i ? ' data-i="' + i + '"' : '') + '>' + h[1] + '°</span>').join('') +
      '<div class="fxv-forecast-pop" data-vt="pop" data-i="6" aria-label="Chance of rain">' + HOURS.map(h => '<span>' + h[3] + '%</span>').join('') + '</div>' +
      '</div>';
  },
  week: () =>
    '<ol class="fxv-forecast-week">' + WEEK.map((d, i) =>
      '<li class="fxv-forecast-row" data-vt="row' + i + '" data-i="' + i + '"><span>' + d[0] + '</span>' + icon(d[1], i ? '' : 'icon') +
      '<span class="p">' + d[2] + '%</span><span class="lo">' + d[3] + '°</span>' + range(d[3], d[4], i ? 'r' + i : 'range') + '<span class="hi">' + d[4] + '°</span></li>').join('') +
    '</ol>'
};

const panel = root.querySelector('.fxv-forecast-panel');
const tabs = [...root.querySelectorAll('[role="tab"]')];
const tablist = root.querySelector('.fxv-forecast-tabs');
let tab = 'now';

function render() {
  panel.innerHTML = VIEWS[tab]();
  tabs.forEach((b, i) => {
    const on = b.dataset.tab === tab;
    b.setAttribute('aria-selected', on ? 'true' : 'false');
    b.tabIndex = on ? 0 : -1;
    if (on) { tablist.style.setProperty('--fxv-forecast-at', i + 1); panel.setAttribute('aria-labelledby', b.id); }
  });
}

/* stagger the entrances: every animation of an item group waits i x 40ms */
function stagger() {
  const wait = new Map();
  panel.querySelectorAll('[data-i][data-vt]').forEach(el => wait.set(vtName(el.dataset.vt), 70 + el.dataset.i * 40));
  ownAnimations().forEach(a => {
    const m = a.effect.pseudoElement.match(/^::view-transition-new\(([^)]+)\)/);
    if (m && wait.has(m[1])) a.effect.updateTiming({ delay: wait.get(m[1]) });
  });
}

function go(next) {
  if (next === tab) return;
  morph(() => { tab = next; render(); }, stagger);
}

root.addEventListener('click', e => {
  const b = e.target.closest('[role="tab"]');
  if (b) go(b.dataset.tab);
});
tablist.addEventListener('keydown', e => {
  const i = tabs.indexOf(document.activeElement);
  const d = { ArrowRight: 1, ArrowLeft: -1 }[e.key];
  let j = d ? (i + d + tabs.length) % tabs.length : e.key === 'Home' ? 0 : e.key === 'End' ? tabs.length - 1 : -1;
  if (j < 0 || i < 0) return;
  e.preventDefault();
  tabs[j].focus();
  go(tabs[j].dataset.tab);
});

/* name the three tab labels too, so they are painted above the moving pill */
tabs.forEach(b => (b.dataset.vt = 'tab-' + b.dataset.tab));
render();

