.fxv-queue {
  --fxv-queue-bg: oklch(0.185 0.012 165);
  --fxv-queue-ink: oklch(0.95 0.012 120);
  --fxv-queue-accent: oklch(0.86 0.15 120);
  --fxv-queue-dim: color-mix(in oklch, var(--fxv-queue-ink) 55%, var(--fxv-queue-bg));
  --fxv-queue-line: color-mix(in oklch, var(--fxv-queue-ink) 11%, transparent);
  --fxv-queue-well: color-mix(in oklch, var(--fxv-queue-ink) 6%, var(--fxv-queue-bg));

  container-type: inline-size;
  view-transition-class: fxv-queue-root;
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  inline-size: 100%;
  max-inline-size: 460px;
  display: grid;
  grid-template-areas: "head" "now" "label" "next";
  row-gap: 10px;
  padding: 14px;
  border-radius: 20px;
  color: var(--fxv-queue-ink);
  font: 12.5px/1.3 system-ui, sans-serif;
  background:
    radial-gradient(110% 60% at 15% 30%, color-mix(in oklch, var(--fxv-queue-tint, var(--fxv-queue-accent)) 16%, transparent), transparent 70%),
    var(--fxv-queue-bg);
  box-shadow: inset 0 0 0 1px var(--fxv-queue-line);

  & .fxv-queue-head {
    grid-area: head;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    min-block-size: 30px;
    & h3 { margin: 0; font-size: 14px; font-weight: 700; letter-spacing: -0.005em; }
  }
  & .fxv-queue-meta { margin: 1px 0 0; color: var(--fxv-queue-dim); font-size: 11px; font-variant-numeric: tabular-nums; }
  & .fxv-queue-played {
    display: flex;
    gap: 5px;
    margin: 0;
    padding: 0;
    list-style: none;
    & li { display: block; }
    & button { all: unset; display: block; cursor: pointer; border-radius: 6px; }
    & button:focus-visible { outline: 2px solid var(--fxv-queue-accent); outline-offset: 2px; }
    & .fxv-queue-art { inline-size: 26px; block-size: 26px; border-radius: 6px; opacity: 0.72; transition: opacity 0.2s, scale 0.2s; }
    & button:hover .fxv-queue-art { opacity: 1; scale: 1.08; }
  }

  /* generative sleeves: five pattern families, three colours each */
  & .fxv-queue-art {
    aspect-ratio: 1;
    border-radius: 8px;
    background: var(--a);
    box-shadow: inset 0 0 0 1px oklch(1 0 0 / 0.08);
    view-transition-class: fxv-queue-art;
    &[data-p="sun"] { background: radial-gradient(circle at 50% 62%, var(--c) 0 18%, var(--b) 18.5% 30%, transparent 30.5%), linear-gradient(var(--a) 0 62%, var(--b) 62%); }
    &[data-p="stripe"] { background: repeating-linear-gradient(135deg, var(--a) 0 12%, var(--b) 12% 18%, var(--a) 18% 24%, var(--c) 24% 26%); }
    &[data-p="rings"] { background: repeating-radial-gradient(circle at 30% 70%, var(--a) 0 9%, var(--b) 9% 14%, var(--c) 14% 16%); }
    &[data-p="split"] { background: linear-gradient(160deg, var(--a) 0 48%, var(--c) 48% 52%, var(--b) 52%); }
    &[data-p="dots"] { background: radial-gradient(circle, var(--c) 0 22%, transparent 24%) 0 0 / 25% 25%, linear-gradient(var(--a), var(--b)); }
  }

  & .fxv-queue-now {
    grid-area: now;
    display: grid;
    grid-template-columns: clamp(92px, 33cqi, 132px) 1fr;
    gap: 12px;
    align-items: stretch;
  }
  & .fxv-queue-nowart .fxv-queue-art { inline-size: 100%; border-radius: 12px; box-shadow: 0 10px 24px -12px oklch(0 0 0 / 0.7), inset 0 0 0 1px oklch(1 0 0 / 0.08); }
  & .fxv-queue-nowinfo { display: grid; grid-template-rows: auto auto 1fr auto auto; min-inline-size: 0; }
  & .fxv-queue-kicker {
    display: flex;
    align-items: center;
    gap: 6px;
    margin: 0 0 4px;
    font-size: 9.5px;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--fxv-queue-accent);
  }
  & .fxv-queue-eq {
    display: inline-flex;
    align-items: end;
    gap: 1.5px;
    block-size: 9px;
    & i { inline-size: 2px; block-size: 100%; background: currentColor; transform-origin: bottom; animation: fxv-queue-eq 0.9s ease-in-out infinite alternate; }
    & i:nth-child(2) { animation-duration: 0.6s; animation-delay: -0.3s; }
    & i:nth-child(3) { animation-duration: 0.75s; animation-delay: -0.5s; }
  }
  &[data-paused] .fxv-queue-eq i { animation-play-state: paused; }
  & .fxv-queue-title {
    display: block;
    inline-size: fit-content;
    max-inline-size: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 700;
    view-transition-class: fxv-queue-text;
  }
  & .fxv-queue-nowtext {
    min-inline-size: 0;
    & .fxv-queue-title { font-size: clamp(14px, 5cqi, 17px); letter-spacing: -0.01em; }
    & .fxv-queue-artist { margin-block-start: 1px; color: var(--fxv-queue-dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
  & .fxv-queue-bar {
    align-self: end;
    block-size: 4px;
    border-radius: 2px;
    background: var(--fxv-queue-line);
    overflow: hidden;
    & i {
      display: block;
      block-size: 100%;
      background: var(--fxv-queue-tint, var(--fxv-queue-accent));
      transform-origin: left;
      transform: scaleX(0);
    }
  }
  & .fxv-queue-times {
    display: flex;
    justify-content: space-between;
    margin: 4px 0 2px;
    font: 10px ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxv-queue-dim);
  }
  & .fxv-queue-ctrl {
    display: flex;
    justify-content: space-between;
    align-items: center;
    & button {
      all: unset;
      inline-size: 30px;
      block-size: 30px;
      display: grid;
      place-items: center;
      border-radius: 50%;
      cursor: pointer;
      color: var(--fxv-queue-ink);
      transition: scale 0.18s cubic-bezier(0.3, 1.6, 0.5, 1), opacity 0.2s;
      &:hover { background: var(--fxv-queue-well); }
      &:active { scale: 0.9; }
      &:focus-visible { outline: 2px solid var(--fxv-queue-accent); outline-offset: 1px; }
      &:disabled { opacity: 0.3; cursor: default; background: none; }
    }
    & svg { inline-size: 17px; block-size: 17px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
    & .fxv-queue-play {
      inline-size: 36px;
      block-size: 36px;
      color: var(--fxv-queue-bg);
      background: var(--fxv-queue-ink);
      &:hover { background: var(--fxv-queue-ink); scale: 1.06; }
      & svg { fill: currentColor; }
    }
  }
  & .fxv-queue-tri { display: none; }
  &[data-paused] .fxv-queue-tri { display: inline; }
  &[data-paused] .fxv-queue-pause { display: none; }

  & .fxv-queue-label {
    grid-area: label;
    margin: 2px 0 0;
    font-size: 9.5px;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--fxv-queue-dim);
  }
  & .fxv-queue-next {
    grid-area: next;
    display: grid;
    gap: 2px;
    margin: 0;
    padding: 0;
    list-style: none;
    block-size: calc(3 * 44px + 4px);
    align-content: start;
  }
  & .fxv-queue-row {
    all: unset;
    box-sizing: border-box;
    display: grid;
    grid-template-columns: 34px 1fr auto;
    align-items: center;
    column-gap: 10px;
    inline-size: 100%;
    block-size: 44px;
    padding: 5px 8px 5px 5px;
    border-radius: 10px;
    cursor: pointer;
    view-transition-class: fxv-queue-row;
    &:hover { background: var(--fxv-queue-well); }
    &:focus-visible { outline: 2px solid var(--fxv-queue-accent); outline-offset: -2px; }
    & .fxv-queue-art { inline-size: 34px; border-radius: 7px; }
    & span { min-inline-size: 0; }
    & .fxv-queue-title { font-size: 12.5px; font-weight: 600; }
    & small { display: block; color: var(--fxv-queue-dim); font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & time { font: 10.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--fxv-queue-dim); }
  }
  & .fxv-queue-done { padding: 14px 6px; color: var(--fxv-queue-dim); }
}

@container (inline-size < 280px) {
  .fxv-queue .fxv-queue-played li:nth-last-child(n + 4) { display: none; }
}

/* Sleeves and titles fly between the history strip, the hero and the queue.
   Every sleeve is square at every size, so cover never crops and the group
   only has to round its corners. */
::view-transition-group(.fxv-queue-art) {
  animation-duration: 0.6s;
  animation-timing-function: linear(0, 0.026, 0.091, 0.181, 0.285, 0.393, 0.499, 0.598, 0.688, 0.766, 0.833, 0.889, 0.933, 0.968, 0.995, 1.013, 1.026, 1.034, 1.038, 1.038, 1.037, 1.034, 1.031, 1.027, 1.023, 1.019, 1.015, 1.012, 1.009, 1.006, 1);
  overflow: clip;
  border-radius: 9px;
}
::view-transition-old(.fxv-queue-art),
::view-transition-new(.fxv-queue-art) { block-size: 100%; object-fit: cover; }
::view-transition-group(.fxv-queue-text),
::view-transition-group(.fxv-queue-row) {
  animation-duration: 0.52s;
  animation-timing-function: linear(0, 0.026, 0.091, 0.181, 0.285, 0.393, 0.499, 0.598, 0.688, 0.766, 0.833, 0.889, 0.933, 0.968, 0.995, 1.013, 1.026, 1.034, 1.038, 1.038, 1.037, 1.034, 1.031, 1.027, 1.023, 1.019, 1.015, 1.012, 1.009, 1.006, 1);
}
::view-transition-new(.fxv-queue-row):only-child { animation: fxv-queue-rise 0.42s 0.12s cubic-bezier(0.2, 0.8, 0.2, 1) both; }
::view-transition-old(.fxv-queue-row):only-child { animation: fxv-queue-sink 0.2s ease-in both; }
::view-transition-new(.fxv-queue-art):only-child { animation: fxv-queue-pop 0.4s 0.1s cubic-bezier(0.3, 1.4, 0.5, 1) both; }
::view-transition-old(.fxv-queue-art):only-child { animation: fxv-queue-sink 0.24s ease-in both; }
::view-transition-group(.fxv-queue-root) { animation-duration: 0.36s; }

@keyframes fxv-queue-rise { from { opacity: 0; transform: translateY(14px); } }
@keyframes fxv-queue-sink { to { opacity: 0; transform: scale(0.85); } }
@keyframes fxv-queue-pop { from { opacity: 0; transform: scale(0.6); } }
@keyframes fxv-queue-eq { from { transform: scaleY(0.25); } to { transform: scaleY(1); } }

@media (prefers-reduced-motion: reduce) {
  .fxv-queue .fxv-queue-eq i { animation: none; transform: scaleY(0.6); }
  .fxv-queue .fxv-queue-ctrl button, .fxv-queue .fxv-queue-played .fxv-queue-art { transition: none; }
  ::view-transition-group(.fxv-queue-root) { animation-duration: 0.2s; }
}

