/* ── view-transition plumbing ─────────────────────────────────────────
   1. root.startViewTransition()     scoped: snapshots only this component, clips
                                      to it, and leaves the rest of the page live
   2. document.startViewTransition() whole-document snapshot; the root is named
                                      for the duration so it animates as one group
   3. FLIP with the Web Animations API when neither exists
   Names carry a per-instance id so two copies on one page never collide.  */
const ID = 'fxv-queue';
const UID = Math.random().toString(36).slice(2, 8);
const ROOT_NAME = ID + '-' + UID;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SCOPED = typeof root.startViewTransition === 'function';
const DOCVT = typeof document.startViewTransition === 'function';
const vtName = key => ROOT_NAME + '-' + key;
const host = () => (SCOPED ? root : document.documentElement);
let running = null;

function nameParts(on) {
  root.querySelectorAll('[data-vt]').forEach(el => {
    el.style.viewTransitionName = on && !RM.matches && el.getClientRects().length ? vtName(el.dataset.vt) : '';
  });
}

function morph(update, onReady, onAbort) {
  if (!SCOPED && !DOCVT) { flip(update); return null; }
  const first = measure();
  nameParts(true);
  root.style.viewTransitionName = ROOT_NAME;
  const run = () => { update(); nameParts(true); };
  const t = SCOPED ? root.startViewTransition(run) : document.startViewTransition(run);
  running = t;
  t.ready.then(() => { if (onReady && !RM.matches) onReady(t); }, e => {
    /* An AbortError just means a newer transition took over. Chrome can also
       abort a scoped transition with InvalidStateError while others run on
       the page; the DOM still updates, so replay the change instead of letting
       it snap: FLIP from the geometry measured above, or the caller's own. */
    if (!e || e.name !== 'InvalidStateError' || RM.matches) return;
    t.updateCallbackDone.then(() => (onAbort ? onAbort() : play(first)), () => {});
  });
  t.finished.finally(() => {
    if (running !== t) return;
    running = null;
    nameParts(false);
    root.style.viewTransitionName = '';
  });
  return t;
}

/* Animate one of this transition's pseudo-elements from script. */
function pseudo(part, key, keyframes, opts) {
  const name = key === 'root' ? ROOT_NAME : vtName(key);
  return host().animate(keyframes, Object.assign({ fill: 'both' }, opts, { pseudoElement: '::view-transition-' + part + '(' + name + ')' }));
}

/* All running animations that belong to one of our named groups. */
function ownAnimations() {
  return host().getAnimations({ subtree: true }).filter(a => {
    const p = a.effect && a.effect.pseudoElement;
    return p && p.indexOf(ROOT_NAME + '-') > -1;
  });
}

/* FLIP: first rects of every outermost [data-vt] element, then invert + play */
const outermost = el => { const p = el.parentElement.closest('[data-vt]'); return !p || !root.contains(p); };
function measure() {
  const m = new Map();
  if (RM.matches) return m;
  root.querySelectorAll('[data-vt]').forEach(el => {
    if (outermost(el) && el.getClientRects().length) m.set(el.dataset.vt, el.getBoundingClientRect());
  });
  return m;
}
function play(first) {
  if (RM.matches || !first) return;
  root.querySelectorAll('[data-vt]').forEach(el => {
    if (!outermost(el)) return;
    const b = el.getBoundingClientRect();
    if (!b.width) return;
    const a = first.get(el.dataset.vt);
    if (!a) {
      el.animate({ opacity: [0, 1], transform: ['scale(.94)', 'none'] }, { duration: 320, easing: 'cubic-bezier(.2,.8,.2,1)', fill: 'backwards' });
      return;
    }
    const dx = a.left - b.left, dy = a.top - b.top, sx = a.width / b.width, sy = a.height / b.height;
    if (Math.abs(dx) + Math.abs(dy) < 1 && Math.abs(sx - 1) + Math.abs(sy - 1) < 0.01) return;
    el.animate({
      transformOrigin: ['0 0', '0 0'],
      transform: ['translate(' + dx + 'px,' + dy + 'px) scale(' + sx + ',' + sy + ')', 'none']
    }, { duration: 520, easing: 'cubic-bezier(.2,.9,.25,1)' });
  });
}
function flip(update) {
  const first = measure();
  update();
  play(first);
}

/* [title, artist, seconds, pattern, colour a, b, c] */
const TRACKS = [
  ['Harbour Lights', 'Ada Brennick', 238, 'sun', 'oklch(0.42 0.09 250)', 'oklch(0.62 0.16 40)', 'oklch(0.9 0.12 85)'],
  ['Copper Wire', 'Maren Holt', 245, 'stripe', 'oklch(0.55 0.13 50)', 'oklch(0.3 0.04 40)', 'oklch(0.85 0.08 70)'],
  ['Field Recording No. 4', 'Tamsin Rye', 176, 'dots', 'oklch(0.7 0.09 140)', 'oklch(0.4 0.07 150)', 'oklch(0.94 0.05 110)'],
  ['Low Tide Hymn', 'Saltwater Choir', 222, 'rings', 'oklch(0.36 0.05 200)', 'oklch(0.62 0.07 195)', 'oklch(0.88 0.05 180)'],
  ['Night Ferry', 'The Kesh Quartet', 318, 'split', 'oklch(0.25 0.04 260)', 'oklch(0.78 0.13 75)', 'oklch(0.95 0.03 90)'],
  ['Pale Fire Escape', 'Odile & the Overpass', 207, 'sun', 'oklch(0.82 0.08 30)', 'oklch(0.58 0.17 25)', 'oklch(0.97 0.02 80)'],
  ['Glasshouse', 'Ruthven Park', 281, 'stripe', 'oklch(0.75 0.1 165)', 'oklch(0.45 0.08 170)', 'oklch(0.95 0.04 140)'],
  ['Undertow', 'Corran Bay Sound System', 362, 'rings', 'oklch(0.3 0.06 300)', 'oklch(0.55 0.15 330)', 'oklch(0.8 0.1 20)'],
  ['Slow Lantern', 'Wren Adair', 213, 'dots', 'oklch(0.32 0.06 50)', 'oklch(0.22 0.03 40)', 'oklch(0.85 0.14 80)'],
  ['Weatherglass', 'Hollin Street', 252, 'split', 'oklch(0.86 0.04 230)', 'oklch(0.5 0.09 235)', 'oklch(0.3 0.04 240)']
];
const SHOW_PLAYED = 4, SHOW_NEXT = 3;
const fmt = s => Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0');
const total = TRACKS.reduce((a, t) => a + t[2], 0);

const $ = s => root.querySelector(s);
const played = $('.fxv-queue-played'), nowArt = $('.fxv-queue-nowart'), nowText = $('.fxv-queue-nowtext');
const next = $('.fxv-queue-next'), bar = $('.fxv-queue-bar'), fill = bar.firstElementChild;
const el = $('.fxv-queue-el'), left = $('.fxv-queue-left'), playBtn = $('[data-act="play"]');
$('.fxv-queue-meta').textContent = TRACKS.length + ' tracks · ' + Math.round(total / 60) + ' min';

/* start late in track 4 so a passer-by sees the hand-off within the minute */
let cur = 3, pos = TRACKS[3][2] - 38, paused = false;

const art = i => {
  const t = TRACKS[i];
  return '<div class="fxv-queue-art" data-vt="art' + i + '" data-p="' + t[3] + '" style="--a:' + t[4] + ';--b:' + t[5] + ';--c:' + t[6] + '"></div>';
};

function render() {
  const t = TRACKS[cur];
  const from = Math.max(0, cur - SHOW_PLAYED);
  played.innerHTML = TRACKS.slice(from, cur).map((p, k) =>
    '<li><button type="button" data-go="' + (from + k) + '" aria-label="Play ' + p[0] + ' again">' + art(from + k) + '</button></li>').join('');
  nowArt.innerHTML = art(cur);
  nowText.innerHTML = '<span class="fxv-queue-title" data-vt="title' + cur + '">' + t[0] + '</span><div class="fxv-queue-artist">' + t[1] + '</div>';
  const up = TRACKS.slice(cur + 1, cur + 1 + SHOW_NEXT);
  next.innerHTML = up.length ? up.map((n, k) => {
    const i = cur + 1 + k;
    return '<li><button type="button" class="fxv-queue-row" data-vt="row' + i + '" data-go="' + i + '" tabindex="' + (k ? -1 : 0) + '">' + art(i) +
      '<span><span class="fxv-queue-title" data-vt="title' + i + '">' + n[0] + '</span><small>' + n[1] + '</small></span><time>' + fmt(n[2]) + '</time></button></li>';
  }).join('') : '<li class="fxv-queue-done">End of the playlist.</li>';
  root.style.setProperty('--fxv-queue-tint', t[5]);
  $('[data-act="prev"]').disabled = cur === 0;
  $('[data-act="next"]').disabled = cur === TRACKS.length - 1;
  bar.setAttribute('aria-valuemax', t[2]);
  paint(true);
}

function paint(force) {
  const t = TRACKS[cur];
  fill.style.transform = 'scaleX(' + (pos / t[2]).toFixed(4) + ')';
  const s = Math.floor(pos);
  if (force || s !== paint.last) {
    paint.last = s;
    el.textContent = fmt(s);
    left.textContent = '-' + fmt(t[2] - s);
    bar.setAttribute('aria-valuenow', s);
    bar.setAttribute('aria-valuetext', fmt(s) + ' of ' + fmt(t[2]));
  }
}

/* pending guards the hand-off: the update callback runs a frame later, and
   the clock must not fire a second transition for the same track meanwhile */
let pending = -1;
function go(i) {
  if (i === cur || i === pending || i < 0 || i >= TRACKS.length) return;
  pending = i;
  morph(() => { cur = i; pos = 0; pending = -1; render(); });
}

function setPaused(p) {
  paused = p;
  if (!p) wake();
  root.toggleAttribute('data-paused', p);
  playBtn.setAttribute('aria-label', p ? 'Play' : 'Pause');
  $('.fxv-queue-state').textContent = p ? 'Paused' : 'Now playing';
}

root.addEventListener('click', e => {
  const g = e.target.closest('[data-go]');
  if (g) { go(+g.dataset.go); return; }
  const a = e.target.closest('[data-act]');
  if (!a || a.disabled) return;
  if (a.dataset.act === 'play') setPaused(!paused);
  else if (a.dataset.act === 'next') go(cur + 1);
  else if (pos > 3) { pos = 0; paint(true); } else go(cur - 1);
});

next.addEventListener('keydown', e => {
  const rows = [...next.querySelectorAll('.fxv-queue-row')];
  const i = rows.indexOf(document.activeElement);
  const d = { ArrowDown: 1, ArrowUp: -1 }[e.key];
  if (i < 0 || !d || !rows[i + d]) return;
  e.preventDefault();
  rows[i].tabIndex = -1;
  rows[i + d].tabIndex = 0;
  rows[i + d].focus();
});

/* the clock: one rAF loop that only runs while playing and on screen; it
   parks itself otherwise and is restarted by play or the observer */
let visible = true, last = 0, raf = 0;
const io = 'IntersectionObserver' in window ? new IntersectionObserver(es => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = es[0].isIntersecting;
  wake();
}) : null;
if (io) io.observe(root);
function wake() { if (!raf && !paused && visible && !document.hidden) { last = 0; raf = requestAnimationFrame(frame); } }
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  wake();
};
document.addEventListener('visibilitychange', onVis);
function frame(now) {
  if (!root.isConnected) return;
  if (paused || !visible || document.hidden) { raf = 0; return; }
  const dt = last ? Math.min(0.25, (now - last) / 1000) : 0;
  last = now;
  if (pending < 0) pos += dt;
  if (pos >= TRACKS[cur][2]) {
    pos = TRACKS[cur][2];
    if (cur < TRACKS.length - 1) go(cur + 1);
    else setPaused(true);
  }
  paint(false);
  raf = requestAnimationFrame(frame);
}
wake();

render();

css:
.fxv-pages {
  --fxv-pages-desk: oklch(0.905 0.024 72);
  --fxv-pages-paper: oklch(0.985 0.011 88);
  --fxv-pages-ink: oklch(0.27 0.03 40);
  --fxv-pages-accent: oklch(0.45 0.13 350);
  --fxv-pages-dim: color-mix(in oklch, var(--fxv-pages-ink) 58%, var(--fxv-pages-paper));
  --fxv-pages-line: color-mix(in oklch, var(--fxv-pages-ink) 12%, transparent);

  container-type: inline-size;
  view-transition-class: fxv-pages-root;
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  inline-size: 100%;
  max-inline-size: 440px;
  display: grid;
  grid-template-rows: auto auto;
  row-gap: 12px;
  padding: 16px 16px 12px;
  border-radius: 18px;
  overflow: clip;
  background:
    radial-gradient(120% 90% at 30% 0%, oklch(1 0 0 / 0.35), transparent 60%),
    var(--fxv-pages-desk);
  color: var(--fxv-pages-ink);
  font: 13px/1.45 system-ui, sans-serif;

  & .fxv-pages-book {
    position: relative;
    /* the edges of the pages still to come, drawn under the open one */
    &::before, &::after {
      content: "";
      position: absolute;
      inset: 4px -3px -3px 4px;
      border-radius: 3px 10px 10px 3px;
      background: color-mix(in oklch, var(--fxv-pages-paper) 92%, var(--fxv-pages-ink));
      box-shadow: 0 1px 2px oklch(0.3 0.04 50 / 0.18);
    }
    &::after { inset: 2px -1.5px -1.5px 2px; background: var(--fxv-pages-paper); }
  }
  & .fxv-pages-page {
    position: relative;
    z-index: 1;
    box-sizing: border-box;
    block-size: 262px;
    display: grid;
    grid-template-rows: auto 1fr;
    padding: 12px 16px 14px 20px;
    border-radius: 3px 10px 10px 3px;
    background:
      linear-gradient(90deg, oklch(0.4 0.04 50 / 0.12), transparent 14px),
      var(--fxv-pages-paper);
    box-shadow: 0 1px 2px oklch(0.3 0.04 50 / 0.2), 0 14px 24px -18px oklch(0.3 0.04 50 / 0.6);
    view-transition-class: fxv-pages-page;
    touch-action: pan-y;
    user-select: none;
  }
  & .fxv-pages-run {
    display: flex;
    justify-content: space-between;
    padding-block-end: 6px;
    margin-block-end: 10px;
    border-block-end: 1px solid var(--fxv-pages-line);
    font: 600 10.5px/1 ui-serif, Georgia, serif;
    font-variant: small-caps;
    letter-spacing: 0.08em;
    color: var(--fxv-pages-dim);
    & span:last-child { font-variant-numeric: oldstyle-nums; letter-spacing: 0; }
  }
  & .fxv-pages-body {
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-areas: "num art" "title art" "text text" "meta meta";
    grid-template-rows: auto auto 1fr auto;
    column-gap: 10px;
    min-block-size: 0;
  }
  & .fxv-pages-num {
    grid-area: num;
    font: 400 44px/0.9 ui-serif, Georgia, serif;
    color: var(--fxv-pages-accent);
    font-variant-numeric: lining-nums;
  }
  & .fxv-pages-title {
    grid-area: title;
    margin: 4px 0 6px;
    font: 600 clamp(18px, 6.4cqi, 22px)/1.1 ui-serif, Georgia, serif;
    letter-spacing: -0.01em;
    text-wrap: balance;
  }
  & .fxv-pages-text { grid-area: text; margin: 0; text-wrap: pretty; color: color-mix(in oklch, var(--fxv-pages-ink) 88%, var(--fxv-pages-paper)); }
  & .fxv-pages-art {
    grid-area: art;
    inline-size: 52px;
    block-size: 52px;
    fill: none;
    stroke: var(--fxv-pages-accent);
    stroke-width: 1.3;
    stroke-linecap: round;
    stroke-linejoin: round;
    opacity: 0.85;
  }
  & .fxv-pages-meta {
    grid-area: meta;
    display: flex;
    gap: 6px;
    margin: 10px 0 0;
    padding: 0;
    list-style: none;
    & li {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      padding: 3px 9px 3px 7px;
      border-radius: 999px;
      font-size: 11.5px;
      font-weight: 600;
      font-variant-numeric: tabular-nums;
      background: color-mix(in oklch, var(--fxv-pages-accent) 9%, var(--fxv-pages-paper));
      color: var(--fxv-pages-accent);
    }
    & svg { inline-size: 13px; block-size: 13px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
  }
  & .fxv-pages-cover {
    & .fxv-pages-kick { margin: 0; font-size: 10.5px; font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--fxv-pages-accent); }
    & .fxv-pages-title { font-size: clamp(21px, 7.6cqi, 27px); margin: 2px 0 4px; }
    & .fxv-pages-text { color: var(--fxv-pages-dim); font-size: 12px; }
  }
  & .fxv-pages-ing {
    grid-area: meta;
    display: grid;
    grid-template-columns: 1fr auto;
    margin: 8px 18px 0 0;
    padding: 0;
    list-style: none;
    font-size: 12px;
    & li { display: contents; }
    & li > * { padding-block: 2.5px; border-block-end: 1px dotted var(--fxv-pages-line); }
    & li:last-child > * { border-block-end: 0; }
    & b { font-weight: 600; font-variant-numeric: tabular-nums; text-align: end; }
  }

  /* dog-ear: grows under the pointer, and lifts now and then to invite a turn */
  & .fxv-pages-ear {
    all: unset;
    position: absolute;
    z-index: 2;
    right: 0;
    bottom: 0;
    inline-size: 30px;
    block-size: 30px;
    border-radius: 0 0 10px 0;
    background: linear-gradient(315deg, var(--fxv-pages-desk) 0 50%, color-mix(in oklch, var(--fxv-pages-paper) 82%, var(--fxv-pages-ink)) 50% 56%, transparent 56%);
    transform-origin: 100% 100%;
    cursor: pointer;
    animation: fxv-pages-peel 5s cubic-bezier(0.4, 0, 0.2, 1) 2s infinite;
    transition: scale 0.3s cubic-bezier(0.3, 1.5, 0.5, 1);
    &:focus-visible { outline: 2px solid var(--fxv-pages-accent); outline-offset: 2px; }
  }
  & .fxv-pages-book:hover .fxv-pages-ear { scale: 1.6; animation: none; }
  &:has(.fxv-pages-page[data-last]) .fxv-pages-ear { display: none; }

  & .fxv-pages-nav {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
  }
  & .fxv-pages-btn {
    all: unset;
    inline-size: 32px;
    block-size: 32px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    cursor: pointer;
    color: var(--fxv-pages-ink);
    transition: background-color 0.15s, scale 0.15s;
    & svg { inline-size: 18px; block-size: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
    &:hover { background: color-mix(in oklch, var(--fxv-pages-ink) 8%, transparent); }
    &:active { scale: 0.9; }
    &:focus-visible { outline: 2px solid var(--fxv-pages-accent); outline-offset: 1px; }
    &:disabled { opacity: 0.3; cursor: default; background: none; }
  }
  & .fxv-pages-dots {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 6px;
    & button {
      all: unset;
      inline-size: 7px;
      block-size: 7px;
      border-radius: 4px;
      background: color-mix(in oklch, var(--fxv-pages-ink) 25%, transparent);
      cursor: pointer;
      view-transition-class: fxv-pages-dot;
      &[aria-current] { inline-size: 22px; background: var(--fxv-pages-accent); }
      &:focus-visible { outline: 2px solid var(--fxv-pages-accent); outline-offset: 2px; }
    }
  }
}

@container (inline-size < 290px) {
  .fxv-pages .fxv-pages-art { inline-size: 40px; block-size: 40px; }
  .fxv-pages .fxv-pages-text { font-size: 12px; }
}

/* The turn is scripted per direction. Here both snapshots are pinned opaque,
   with no cross-fade, so the turning sheet reads as paper, not a dissolve. */
::view-transition-group(.fxv-pages-page) { animation-duration: 0.64s; }
::view-transition-old(.fxv-pages-page),
::view-transition-new(.fxv-pages-page) {
  animation: none;
  mix-blend-mode: normal;
  backface-visibility: hidden;
}
::view-transition-group(.fxv-pages-dot) {
  animation-duration: 0.42s;
  animation-timing-function: cubic-bezier(0.3, 1.3, 0.5, 1);
}
::view-transition-group(.fxv-pages-root) { animation-duration: 0.3s; }

@keyframes fxv-pages-peel {
  0%, 78%, 100% { transform: none; }
  86% { transform: scale(1.45) rotate(-3deg); }
  92% { transform: scale(1.15); }
}
@keyframes fxv-pages-fade-in { from { opacity: 0; } }

@media (prefers-reduced-motion: reduce) {
  .fxv-pages .fxv-pages-ear { animation: none; transition: none; }
  .fxv-pages .fxv-pages-book:hover .fxv-pages-ear { scale: 1; }
  .fxv-pages .fxv-pages-btn { transition: none; }
  /* calm version: no turn, the next page fades in over the last */
  ::view-transition-new(.fxv-pages-page) { animation: fxv-pages-fade-in 0.22s ease both; }
}

