/* ── view-transition plumbing ─────────────────────────────────────────
   1. root.startViewTransition()     scoped: snapshots only this component, clips
                                      to it, and leaves the rest of the page live
   2. document.startViewTransition() whole-document snapshot; the root is named
                                      for the duration so it animates as one group
   3. FLIP with the Web Animations API when neither exists
   Names carry a per-instance id so two copies on one page never collide.  */
const ID = 'fxv-pages';
const UID = Math.random().toString(36).slice(2, 8);
const ROOT_NAME = ID + '-' + UID;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SCOPED = typeof root.startViewTransition === 'function';
const DOCVT = typeof document.startViewTransition === 'function';
const vtName = key => ROOT_NAME + '-' + key;
const host = () => (SCOPED ? root : document.documentElement);
let running = null;

function nameParts(on) {
  root.querySelectorAll('[data-vt]').forEach(el => {
    el.style.viewTransitionName = on && !RM.matches && el.getClientRects().length ? vtName(el.dataset.vt) : '';
  });
}

function morph(update, onReady, onAbort) {
  if (!SCOPED && !DOCVT) { flip(update); return null; }
  const first = measure();
  nameParts(true);
  root.style.viewTransitionName = ROOT_NAME;
  const run = () => { update(); nameParts(true); };
  const t = SCOPED ? root.startViewTransition(run) : document.startViewTransition(run);
  running = t;
  t.ready.then(() => { if (onReady && !RM.matches) onReady(t); }, e => {
    /* An AbortError just means a newer transition took over. Chrome can also
       abort a scoped transition with InvalidStateError while others run on
       the page; the DOM still updates, so replay the change instead of letting
       it snap: FLIP from the geometry measured above, or the caller's own. */
    if (!e || e.name !== 'InvalidStateError' || RM.matches) return;
    t.updateCallbackDone.then(() => (onAbort ? onAbort() : play(first)), () => {});
  });
  t.finished.finally(() => {
    if (running !== t) return;
    running = null;
    nameParts(false);
    root.style.viewTransitionName = '';
  });
  return t;
}

/* Animate one of this transition's pseudo-elements from script. */
function pseudo(part, key, keyframes, opts) {
  const name = key === 'root' ? ROOT_NAME : vtName(key);
  return host().animate(keyframes, Object.assign({ fill: 'both' }, opts, { pseudoElement: '::view-transition-' + part + '(' + name + ')' }));
}

/* All running animations that belong to one of our named groups. */
function ownAnimations() {
  return host().getAnimations({ subtree: true }).filter(a => {
    const p = a.effect && a.effect.pseudoElement;
    return p && p.indexOf(ROOT_NAME + '-') > -1;
  });
}

/* FLIP: first rects of every outermost [data-vt] element, then invert + play */
const outermost = el => { const p = el.parentElement.closest('[data-vt]'); return !p || !root.contains(p); };
function measure() {
  const m = new Map();
  if (RM.matches) return m;
  root.querySelectorAll('[data-vt]').forEach(el => {
    if (outermost(el) && el.getClientRects().length) m.set(el.dataset.vt, el.getBoundingClientRect());
  });
  return m;
}
function play(first) {
  if (RM.matches || !first) return;
  root.querySelectorAll('[data-vt]').forEach(el => {
    if (!outermost(el)) return;
    const b = el.getBoundingClientRect();
    if (!b.width) return;
    const a = first.get(el.dataset.vt);
    if (!a) {
      el.animate({ opacity: [0, 1], transform: ['scale(.94)', 'none'] }, { duration: 320, easing: 'cubic-bezier(.2,.8,.2,1)', fill: 'backwards' });
      return;
    }
    const dx = a.left - b.left, dy = a.top - b.top, sx = a.width / b.width, sy = a.height / b.height;
    if (Math.abs(dx) + Math.abs(dy) < 1 && Math.abs(sx - 1) + Math.abs(sy - 1) < 0.01) return;
    el.animate({
      transformOrigin: ['0 0', '0 0'],
      transform: ['translate(' + dx + 'px,' + dy + 'px) scale(' + sx + ',' + sy + ')', 'none']
    }, { duration: 520, easing: 'cubic-bezier(.2,.9,.25,1)' });
  });
}
function flip(update) {
  const first = measure();
  update();
  play(first);
}

const ICON = {
  plum: '<ellipse cx="12" cy="14.2" rx="6" ry="6.6"/><path d="M12 7.6c0-1.9.7-3.4 1.9-4.4"/><path d="M13.9 4.6c2.4-.6 4.5.3 5.6 2.4-2.5.9-4.6.3-5.6-2.4Z"/><path d="M11.6 9c-1.2 2.4-1.2 8.4.2 11.6"/>',
  bowl: '<path d="M3.5 11.5h17a8.5 8.5 0 0 1-17 0Z"/><path d="M8.5 20.5h7"/><circle cx="9" cy="8.6" r="1.7"/><circle cx="12.6" cy="7.4" r="1.7"/><circle cx="15.6" cy="9.4" r="1.5"/>',
  pan: '<path d="M3.5 11h13v3.8a4.2 4.2 0 0 1-4.2 4.2H7.7a4.2 4.2 0 0 1-4.2-4.2Z"/><path d="M16.5 12.6h4.5"/><path d="M7 8.4c0-1.1 1-1.5 1-2.6M10 8.4c0-1.1 1-1.5 1-2.6M13 8.4c0-1.1 1-1.5 1-2.6"/>',
  spoon: '<ellipse cx="8.2" cy="7.6" rx="3.4" ry="4.6" transform="rotate(-38 8.2 7.6)"/><path d="m10.8 11.2 8.7 8.7"/><path d="M16 5.5h.01M18.5 7.5h.01M17 9.5h.01"/>',
  temp: '<path d="M10 4.6a2 2 0 0 1 4 0v9.2a4 4 0 1 1-4 0Z"/><path d="M12 9v7.3"/><path d="M16.8 6h2.2M16.8 9h2.2M16.8 12h1.4"/>',
  jar: '<path d="M7.5 4h9v3.4h-9Z"/><path d="M7 7.4h10v2.2c1.3.8 2 2 2 3.6V18a2.5 2.5 0 0 1-2.5 2.5h-9A2.5 2.5 0 0 1 5 18v-4.8c0-1.6.7-2.8 2-3.6Z"/><path d="M9 14.2h6"/>'
};
const CLOCK = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 7.5V12l3 2"/></svg>';
const FLAME = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.5a6 6 0 0 0 6-6c0-3.5-2.5-5.5-3.5-9-2 1.5-3 3.5-3 5.5-1-.5-1.8-1.5-2-2.8C8 9.8 6 12 6 14.5a6 6 0 0 0 6 6Z"/></svg>';
/* minutes per step sum to the hour promised on the cover */
const STEPS = [
  ['Wash &amp; stone', 'Rinse the damsons, split each one with your thumbs and flick the stone out over a bowl so no juice is lost.', 15, '', 'bowl'],
  ['Simmer', 'Tip the fruit into a wide pan with the water and bay leaves. Simmer until the skins soften and split.', 20, 'Low heat', 'pan'],
  ['Add the sugar', 'Take the pan off the heat and stir in the sugar until you can feel no grains left on the spoon.', 5, 'Off the heat', 'spoon'],
  ['Boil to set', 'Return to a rolling boil and hold it there until a thermometer reads 105&nbsp;&deg;C, or a drop wrinkles on a cold saucer.', 10, 'High heat', 'temp'],
  ['Pot &amp; seal', 'Lift out the bay, ladle into five warm 340&nbsp;g jars and seal at once. Label them when cool.', 10, '', 'jar']
];
const MINUTES = STEPS.reduce((a, s) => a + s[2], 0);
const PAGES = STEPS.length + 1, FIRST_FOLIO = 12;
const svg = k => '<svg class="fxv-pages-art" viewBox="0 0 24 24" aria-hidden="true">' + ICON[k] + '</svg>';

const page = root.querySelector('.fxv-pages-page');
const dots = root.querySelector('.fxv-pages-dots');
const prevB = root.querySelector('.fxv-pages-btn[data-act="prev"]');
const nextB = root.querySelector('.fxv-pages-btn[data-act="next"]');
let at = 0;

dots.innerHTML = Array.from({ length: PAGES }, (_, i) =>
  '<button type="button" data-go="' + i + '" data-vt="dot' + i + '" aria-label="' + (i ? 'Step ' + i : 'Cover') + '"></button>').join('');

function render() {
  const head = '<header class="fxv-pages-run"><span>The Hedgerow Cook</span><span>' + (FIRST_FOLIO + at) + '</span></header>';
  if (at === 0) {
    page.innerHTML = head + '<div class="fxv-pages-body fxv-pages-cover">' +
      '<p class="fxv-pages-kick" style="grid-area:num">Preserves &middot; No.&nbsp;7</p>' + svg('plum') +
      '<h3 class="fxv-pages-title">Damson &amp; Bay Jam</h3>' +
      '<p class="fxv-pages-text">5 jars of 340&nbsp;g &middot; ' + STEPS.length + ' steps &middot; ' + (MINUTES === 60 ? '1 hour' : MINUTES + ' min') + '</p>' +
      '<ul class="fxv-pages-ing"><li><span>Damsons</span><b>1.2 kg</b></li><li><span>Granulated sugar</span><b>1 kg</b></li><li><span>Water</span><b>300 ml</b></li><li><span>Bay leaves</span><b>2</b></li></ul></div>';
  } else {
    const s = STEPS[at - 1];
    page.innerHTML = head + '<div class="fxv-pages-body"><span class="fxv-pages-num">' + at + '</span>' + svg(s[4]) +
      '<h3 class="fxv-pages-title">' + s[0] + '</h3><p class="fxv-pages-text">' + s[1] + '</p>' +
      '<ul class="fxv-pages-meta"><li>' + CLOCK + s[2] + ' min</li>' + (s[3] ? '<li>' + FLAME + s[3] + '</li>' : '') + '</ul></div>';
  }
  page.toggleAttribute('data-last', at === PAGES - 1);
  page.setAttribute('aria-label', at ? 'Step ' + at + ' of ' + STEPS.length : 'Cover');
  [...dots.children].forEach((d, i) => d.toggleAttribute('aria-current', i === at));
  prevB.disabled = at === 0;
  nextB.disabled = at === PAGES - 1;
}

/* Forward: the old sheet lifts off its spine (rotateY about the left edge,
   in perspective) and darkens as it turns away, on top of the new page.
   Back: the new sheet swings down over the old one. */
function turn(to) {
  if (to < 0 || to >= PAGES || to === at) return;
  const fwd = to > at;
  /* without a transition (or if one is aborted): a short swing of the new page */
  const settle = () => {
    if (!RM.matches) page.animate({ transform: [fwd ? 'perspective(1200px) rotateY(18deg)' : 'perspective(1200px) rotateY(-18deg)', 'none'], opacity: [0.4, 1], transformOrigin: ['0 50%', '0 50%'] }, { duration: 380, easing: 'cubic-bezier(.2,.8,.2,1)' });
  };
  if (!SCOPED && !DOCVT) { at = to; render(); settle(); return; }
  morph(() => { at = to; render(); }, () => {
    const lift = [
      { transform: 'perspective(1200px) rotateY(0deg)', filter: 'brightness(1)', transformOrigin: '0 50%', zIndex: 2 },
      { transform: 'perspective(1200px) rotateY(-30deg)', filter: 'brightness(.97)', transformOrigin: '0 50%', zIndex: 2, offset: 0.35 },
      { transform: 'perspective(1200px) rotateY(-92deg)', filter: 'brightness(.62)', transformOrigin: '0 50%', zIndex: 2 }
    ];
    const shade = [{ filter: 'brightness(.84)' }, { filter: 'brightness(1)' }];
    if (fwd) {
      pseudo('old', 'page', lift, { duration: 640, easing: 'cubic-bezier(.45,.05,.55,.95)' });
      pseudo('new', 'page', shade, { duration: 640, easing: 'ease-out' });
    } else {
      pseudo('new', 'page', lift.slice().reverse().map((k, i) => Object.assign({}, k, { offset: [0, 0.65, 1][i] })), { duration: 640, easing: 'cubic-bezier(.3,.6,.25,1)' });
      pseudo('old', 'page', shade.slice().reverse(), { duration: 640, easing: 'ease-in' });
    }
  }, settle);
}

root.addEventListener('click', e => {
  const g = e.target.closest('[data-go]');
  if (g) { turn(+g.dataset.go); return; }
  const a = e.target.closest('[data-act]');
  if (a) turn(at + (a.dataset.act === 'next' ? 1 : -1));
});
root.addEventListener('keydown', e => {
  if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
    e.preventDefault();
    turn(at + (e.key === 'ArrowRight' ? 1 : -1));
  }
});

/* swipe: a horizontal drag of 40px turns the page that way */
let sx = null, sy = 0;
page.addEventListener('pointerdown', e => { sx = e.clientX; sy = e.clientY; });
page.addEventListener('pointerup', e => {
  if (sx === null) return;
  const dx = e.clientX - sx, dy = e.clientY - sy;
  sx = null;
  if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy)) turn(at + (dx < 0 ? 1 : -1));
});
page.addEventListener('pointercancel', () => { sx = null; });

render();

