.fxv-contact {
  --fxv-contact-bg: oklch(0.175 0.01 32);
  --fxv-contact-ink: oklch(0.93 0.016 75);
  --fxv-contact-safe: oklch(0.62 0.2 28);
  --fxv-contact-edge: oklch(0.76 0.13 66);
  --fxv-contact-dim: color-mix(in oklch, var(--fxv-contact-ink) 52%, var(--fxv-contact-bg));
  --fxv-contact-line: color-mix(in oklch, var(--fxv-contact-ink) 12%, transparent);

  container-type: inline-size;
  view-transition-class: fxv-contact-root;
  grid-template-columns: minmax(0, 1fr);
  box-sizing: border-box;
  inline-size: 100%;
  max-inline-size: 460px;
  display: grid;
  grid-template-rows: auto auto;
  row-gap: 12px;
  padding: 14px;
  border-radius: 18px;
  position: relative;
  isolation: isolate;
  color: var(--fxv-contact-ink);
  font: 12.5px/1.35 system-ui, sans-serif;
  background: var(--fxv-contact-bg);
  box-shadow: inset 0 0 0 1px var(--fxv-contact-line);

  /* safelight: a warm glow that breathes, opacity only */
  &::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: radial-gradient(80% 60% at 50% -10%, color-mix(in oklch, var(--fxv-contact-safe) 26%, transparent), transparent 70%);
    animation: fxv-contact-safelight 4.5s ease-in-out infinite alternate;
    pointer-events: none;
  }

  & .fxv-contact-head {
    display: flex;
    align-items: center;
    gap: 8px;
    min-block-size: 30px;
    & h3 { margin: 0; font-size: 14px; font-weight: 700; white-space: nowrap; }
    & h3 span { color: var(--fxv-contact-dim); font-weight: 500; margin-inline-start: 4px; }
  }
  & .fxv-contact-count {
    margin: 0 0 0 auto;
    font: 10.5px ui-monospace, Menlo, monospace;
    font-variant-numeric: tabular-nums;
    color: var(--fxv-contact-edge);
    white-space: nowrap;
  }
  & .fxv-contact-icon {
    all: unset;
    inline-size: 30px;
    block-size: 30px;
    display: grid;
    place-items: center;
    flex: none;
    border-radius: 8px;
    cursor: pointer;
    transition: background-color 0.15s, scale 0.15s;
    & svg { inline-size: 18px; block-size: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
    &:hover { background: color-mix(in oklch, var(--fxv-contact-ink) 10%, transparent); }
    &:active { scale: 0.9; }
    &:focus-visible { outline: 2px solid var(--fxv-contact-safe); outline-offset: 1px; }
    &:disabled { opacity: 0.3; cursor: default; background: none; }
    &[hidden] { display: none; }
  }

  /* one height for both states, driven by the loupe: a 3:2 frame plus caption */
  & .fxv-contact-area { block-size: calc(100cqi * 2 / 3 + 50px); display: grid; }
  & .fxv-contact-sheet {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    align-content: center;
    gap: 12px 8px;
    margin: 0;
    padding: 0;
    list-style: none;
    &[hidden] { display: none; }
  }
  & .fxv-contact-thumb {
    all: unset;
    box-sizing: border-box;
    inline-size: 100%;
    display: grid;
    gap: 5px;
    cursor: pointer;
    position: relative;
    & small {
      font: 9.5px ui-monospace, Menlo, monospace;
      letter-spacing: 0.06em;
      color: var(--fxv-contact-edge);
      font-variant-numeric: tabular-nums;
    }
    &:focus-visible .fxv-contact-win { outline: 2px solid var(--fxv-contact-ink); outline-offset: 2px; }
    &:hover .fxv-contact-art { scale: 1.08; }
  }
  /* the window crops; the art inside is always 3:2 and centred */
  & .fxv-contact-win {
    position: relative;
    overflow: hidden;
    /* an item with an aspect-ratio does not stretch by default: size it */
    inline-size: 100%;
    aspect-ratio: 1;
    border-radius: 4px;
    background: oklch(0.1 0 0);
    view-transition-class: fxv-contact-frame;
  }
  & .fxv-contact-art {
    position: absolute;
    block-size: 100%;
    aspect-ratio: 3 / 2;
    left: 50%;
    translate: -50% 0;
    transition: scale 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
  }
  /* grease-pencil pick on the contact sheet */
  & .fxv-contact-pick::after {
    content: "";
    position: absolute;
    inset: -5px -5px 13px;
    border: 2px solid var(--fxv-contact-safe);
    border-radius: 48% 52% 46% 54% / 55% 45% 55% 45%;
    rotate: -4deg;
    pointer-events: none;
  }

  & .fxv-contact-loupe {
    display: grid;
    grid-template-rows: auto auto;
    align-content: start;
    gap: 10px;
    margin: 0;
    &[hidden] { display: none; }
    & .fxv-contact-win { aspect-ratio: 3 / 2; border-radius: 6px; box-shadow: 0 18px 30px -18px oklch(0 0 0 / 0.9); }
    & .fxv-contact-art { inline-size: 100%; block-size: 100%; }
    & figcaption {
      display: grid;
      grid-template-columns: 1fr auto auto;
      align-items: center;
      gap: 4px;
      & div { display: grid; min-inline-size: 0; }
      & b { font-weight: 650; font-size: 13.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
      & span { font: 10.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--fxv-contact-dim); }
    }
  }

  /* six scenes in layered gradients, laid out in a 3:2 box */
  & [data-art="dawn"] {
    background:
      radial-gradient(circle at 62% 58%, oklch(0.97 0.06 90) 0 4%, oklch(0.9 0.1 70 / 0.6) 7%, transparent 22%),
      linear-gradient(90deg, transparent 58%, oklch(0.95 0.08 80 / 0.55) 60% 64%, transparent 66%) 0 100% / 100% 38% no-repeat,
      linear-gradient(oklch(0.33 0.05 260) 0 0) 0 100% / 100% 38% no-repeat,
      linear-gradient(oklch(0.55 0.1 330), oklch(0.78 0.12 40) 48%, oklch(0.9 0.09 85) 62%);
  }
  & [data-art="marsh"] {
    background:
      radial-gradient(60% 18% at 30% 78%, oklch(0.78 0.03 220) 0 40%, transparent 42%),
      radial-gradient(45% 10% at 72% 70%, oklch(0.78 0.03 220) 0 40%, transparent 42%),
      radial-gradient(30% 8% at 55% 90%, oklch(0.78 0.03 220) 0 40%, transparent 42%),
      linear-gradient(oklch(0.47 0.06 135) 0 0) 0 100% / 100% 45% no-repeat,
      linear-gradient(oklch(0.38 0.05 140) 0 0) 0 55.5% / 100% 3% no-repeat,
      linear-gradient(oklch(0.7 0.02 230), oklch(0.84 0.015 200));
  }
  & [data-art="wake"] {
    background:
      radial-gradient(circle at 50% 22%, oklch(0.95 0.01 90) 0 1.6%, transparent 2%),
      conic-gradient(from 168deg at 50% 22%, transparent 0deg, oklch(0.92 0.02 200 / 0.75) 4deg 6deg, transparent 9deg 15deg, oklch(0.92 0.02 200 / 0.75) 18deg 20deg, transparent 23deg),
      radial-gradient(120% 90% at 50% 0%, oklch(0.5 0.07 200), oklch(0.32 0.06 220));
  }
  & [data-art="lamps"] {
    background:
      radial-gradient(circle at 14% 46%, oklch(0.92 0.12 80) 0 1.6%, transparent 3.5%),
      radial-gradient(circle at 34% 46%, oklch(0.92 0.12 80) 0 1.6%, transparent 3.5%),
      radial-gradient(circle at 54% 46%, oklch(0.92 0.12 80) 0 1.6%, transparent 3.5%),
      radial-gradient(circle at 74% 46%, oklch(0.92 0.12 80) 0 1.6%, transparent 3.5%),
      radial-gradient(circle at 94% 46%, oklch(0.92 0.12 80) 0 1.6%, transparent 3.5%),
      repeating-linear-gradient(90deg, transparent 0 12.6%, oklch(0.8 0.12 75 / 0.45) 12.6% 15.4%, transparent 15.4% 20%) 0 100% / 100% 44% no-repeat,
      linear-gradient(oklch(0.2 0.03 250) 0 0) 0 100% / 100% 44% no-repeat,
      linear-gradient(oklch(0.17 0.03 265), oklch(0.27 0.05 255));
  }
  & [data-art="dune"] {
    background:
      repeating-linear-gradient(72deg, transparent 0 3%, oklch(0.55 0.08 120 / 0.7) 3% 3.6%, transparent 3.6% 6%) 0 100% / 60% 46% no-repeat,
      radial-gradient(140% 60% at 80% 100%, oklch(0.84 0.07 80) 0 55%, transparent 56%),
      radial-gradient(120% 70% at 10% 100%, oklch(0.78 0.08 75) 0 60%, transparent 61%),
      linear-gradient(oklch(0.62 0.11 240), oklch(0.85 0.05 220));
  }
  & [data-art="storm"] {
    background:
      conic-gradient(from 160deg at 70% 0%, transparent 0deg, oklch(0.85 0.02 90 / 0.28) 6deg 9deg, transparent 13deg 20deg, oklch(0.85 0.02 90 / 0.22) 23deg 25deg, transparent 29deg),
      linear-gradient(oklch(0.3 0.02 240) 0 0) 0 100% / 100% 34% no-repeat,
      linear-gradient(oklch(0.75 0.03 90) 0 0) 0 66% / 100% 1.6% no-repeat,
      linear-gradient(oklch(0.24 0.02 260), oklch(0.46 0.03 250) 64%);
  }
}

@container (inline-size < 290px) {
  .fxv-contact .fxv-contact-head h3 span { display: none; }
}

/* Thumbnail <-> loupe: the window's group clips and both snapshots are drawn
   with object-fit: cover, so the square crop opens out to the full 3:2 frame
   (and closes back down) instead of stretching. */
::view-transition-group(.fxv-contact-frame) {
  animation-duration: 0.58s;
  animation-timing-function: linear(0, 0.026, 0.091, 0.181, 0.285, 0.393, 0.499, 0.598, 0.688, 0.766, 0.833, 0.889, 0.933, 0.968, 0.995, 1.013, 1.026, 1.034, 1.038, 1.038, 1.037, 1.034, 1.031, 1.027, 1.023, 1.019, 1.015, 1.012, 1.009, 1.006, 1);
  overflow: clip;
  border-radius: 5px;
}
::view-transition-old(.fxv-contact-frame),
::view-transition-new(.fxv-contact-frame) {
  block-size: 100%;
  object-fit: cover;
}
::view-transition-group(.fxv-contact-root) { animation-duration: 0.32s; }

@keyframes fxv-contact-safelight { from { opacity: 0.55; } to { opacity: 1; } }

@media (prefers-reduced-motion: reduce) {
  .fxv-contact::before { animation: none; }
  .fxv-contact .fxv-contact-art, .fxv-contact .fxv-contact-icon { transition: none; }
  .fxv-contact .fxv-contact-thumb:hover .fxv-contact-art { scale: 1; }
  ::view-transition-group(.fxv-contact-root) { animation-duration: 0.2s; }
}

