/* ── view-transition plumbing ─────────────────────────────────────────
   1. root.startViewTransition()     scoped: snapshots only this component, clips
                                      to it, and leaves the rest of the page live
   2. document.startViewTransition() whole-document snapshot; the root is named
                                      for the duration so it animates as one group
   3. FLIP with the Web Animations API when neither exists
   Names carry a per-instance id so two copies on one page never collide.  */
const ID = 'fxv-contact';
const UID = Math.random().toString(36).slice(2, 8);
const ROOT_NAME = ID + '-' + UID;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SCOPED = typeof root.startViewTransition === 'function';
const DOCVT = typeof document.startViewTransition === 'function';
const vtName = key => ROOT_NAME + '-' + key;
const host = () => (SCOPED ? root : document.documentElement);
let running = null;

function nameParts(on) {
  root.querySelectorAll('[data-vt]').forEach(el => {
    el.style.viewTransitionName = on && !RM.matches && el.getClientRects().length ? vtName(el.dataset.vt) : '';
  });
}

function morph(update, onReady, onAbort) {
  if (!SCOPED && !DOCVT) { flip(update); return null; }
  const first = measure();
  nameParts(true);
  root.style.viewTransitionName = ROOT_NAME;
  const run = () => { update(); nameParts(true); };
  const t = SCOPED ? root.startViewTransition(run) : document.startViewTransition(run);
  running = t;
  t.ready.then(() => { if (onReady && !RM.matches) onReady(t); }, e => {
    /* An AbortError just means a newer transition took over. Chrome can also
       abort a scoped transition with InvalidStateError while others run on
       the page; the DOM still updates, so replay the change instead of letting
       it snap: FLIP from the geometry measured above, or the caller's own. */
    if (!e || e.name !== 'InvalidStateError' || RM.matches) return;
    t.updateCallbackDone.then(() => (onAbort ? onAbort() : play(first)), () => {});
  });
  t.finished.finally(() => {
    if (running !== t) return;
    running = null;
    nameParts(false);
    root.style.viewTransitionName = '';
  });
  return t;
}

/* Animate one of this transition's pseudo-elements from script. */
function pseudo(part, key, keyframes, opts) {
  const name = key === 'root' ? ROOT_NAME : vtName(key);
  return host().animate(keyframes, Object.assign({ fill: 'both' }, opts, { pseudoElement: '::view-transition-' + part + '(' + name + ')' }));
}

/* All running animations that belong to one of our named groups. */
function ownAnimations() {
  return host().getAnimations({ subtree: true }).filter(a => {
    const p = a.effect && a.effect.pseudoElement;
    return p && p.indexOf(ROOT_NAME + '-') > -1;
  });
}

/* FLIP: first rects of every outermost [data-vt] element, then invert + play */
const outermost = el => { const p = el.parentElement.closest('[data-vt]'); return !p || !root.contains(p); };
function measure() {
  const m = new Map();
  if (RM.matches) return m;
  root.querySelectorAll('[data-vt]').forEach(el => {
    if (outermost(el) && el.getClientRects().length) m.set(el.dataset.vt, el.getBoundingClientRect());
  });
  return m;
}
function play(first) {
  if (RM.matches || !first) return;
  root.querySelectorAll('[data-vt]').forEach(el => {
    if (!outermost(el)) return;
    const b = el.getBoundingClientRect();
    if (!b.width) return;
    const a = first.get(el.dataset.vt);
    if (!a) {
      el.animate({ opacity: [0, 1], transform: ['scale(.94)', 'none'] }, { duration: 320, easing: 'cubic-bezier(.2,.8,.2,1)', fill: 'backwards' });
      return;
    }
    const dx = a.left - b.left, dy = a.top - b.top, sx = a.width / b.width, sy = a.height / b.height;
    if (Math.abs(dx) + Math.abs(dy) < 1 && Math.abs(sx - 1) + Math.abs(sy - 1) < 0.01) return;
    el.animate({
      transformOrigin: ['0 0', '0 0'],
      transform: ['translate(' + dx + 'px,' + dy + 'px) scale(' + sx + ',' + sy + ')', 'none']
    }, { duration: 520, easing: 'cubic-bezier(.2,.9,.25,1)' });
  });
}
function flip(update) {
  const first = measure();
  update();
  play(first);
}

/* [scene, title, edge number, exposure] */
const FRAMES = [
  ['dawn', 'Dawn over Kesh Sound', '14A', 'f/5.6 · 1/125 s'],
  ['marsh', 'Saltmarsh at low water', '15', 'f/8 · 1/250 s'],
  ['wake', 'Ferry wake, mid-channel', '15A', 'f/11 · 1/500 s'],
  ['lamps', 'Harbour lamps', '16', 'f/2.8 · 1/15 s'],
  ['dune', 'Marram on the north dune', '16A', 'f/16 · 1/500 s'],
  ['storm', 'Squall line from the pier', '17', 'f/8 · 1/60 s']
];
const PICK = 2;
const $ = s => root.querySelector(s);
const sheet = $('.fxv-contact-sheet'), loupe = $('.fxv-contact-loupe'), big = $('.fxv-contact-big');
const closeB = $('[data-act="close"]'), prevB = $('[data-act="prev"]'), nextB = $('[data-act="next"]');
const title = $('.fxv-contact-title'), exif = $('.fxv-contact-exif'), count = $('.fxv-contact-count');
let open = -1, at = 0;

const win = (i, named) => '<div class="fxv-contact-win"' + (named ? ' data-vt="f' + i + '"' : '') + '><div class="fxv-contact-art" data-art="' + FRAMES[i][0] + '"></div></div>';

sheet.innerHTML = FRAMES.map((f, i) =>
  '<li><button type="button" class="fxv-contact-thumb' + (i === PICK ? ' fxv-contact-pick' : '') + '" data-i="' + i + '" tabindex="' + (i ? -1 : 0) + '" aria-label="Frame ' + f[2] + ', ' + f[1] + (i === PICK ? ', marked as the pick' : '') + '">' +
  win(i, false) + '<small>▸ ' + f[2] + '</small></button></li>').join('');
const thumbs = [...sheet.querySelectorAll('.fxv-contact-thumb')];

function render() {
  const isOpen = open > -1;
  sheet.hidden = isOpen;
  loupe.hidden = !isOpen;
  closeB.hidden = !isOpen;
  root.dataset.mode = isOpen ? 'loupe' : 'sheet';
  if (isOpen) {
    const f = FRAMES[open];
    big.innerHTML = win(open, true);
    title.textContent = f[1];
    exif.textContent = 'Frame ' + f[2] + ' · ' + f[3];
    count.textContent = (open + 1) + ' / ' + FRAMES.length;
    prevB.disabled = open === 0;
    nextB.disabled = open === FRAMES.length - 1;
  } else {
    big.innerHTML = '';
    count.textContent = FRAMES.length + ' selects of 36';
  }
}

/* only the frame that travels is named; the rest of the sheet stays in the
   root snapshot and fades underneath it instead of painting over it */
function tagThumb(i) {
  thumbs.forEach((t, k) => {
    const w = t.querySelector('.fxv-contact-win');
    if (k === i) w.dataset.vt = 'f' + k;
    else { w.removeAttribute('data-vt'); w.style.viewTransitionName = ''; }
  });
}
function show(i) {
  if (open > -1) return;
  tagThumb(i);
  morph(() => { open = i; render(); closeB.focus({ preventScroll: true }); });
}
function close() {
  if (open < 0) return;
  const back = open;
  morph(() => {
    open = -1;
    tagThumb(back);
    render();
    thumbs.forEach((t, k) => (t.tabIndex = k === back ? 0 : -1));
    thumbs[back].focus({ preventScroll: true });
  });
}
/* inside the loupe: the outgoing frame slides out of the window and the
   incoming one slides in, each clipped by its own group */
function step(d) {
  const to = open + d;
  if (open < 0 || to < 0 || to >= FRAMES.length) return;
  const from = open;
  morph(() => { open = to; render(); }, () => {
    const t = { duration: 420, easing: 'cubic-bezier(.3,.7,.2,1)' };
    pseudo('old', 'f' + from, { transform: ['translateX(0)', 'translateX(' + (-d * 30) + '%)'], opacity: [1, 0] }, t);
    pseudo('new', 'f' + to, { transform: ['translateX(' + (d * 30) + '%)', 'translateX(0)'], opacity: [0, 1] }, t);
  });
}

root.addEventListener('click', e => {
  const t = e.target.closest('.fxv-contact-thumb');
  if (t) { show(+t.dataset.i); return; }
  const a = e.target.closest('[data-act]');
  if (!a || a.disabled) return;
  if (a.dataset.act === 'close') close();
  else step(a.dataset.act === 'next' ? 1 : -1);
});
big.addEventListener('click', () => close());

root.addEventListener('keydown', e => {
  if (open > -1) {
    if (e.key === 'Escape') { e.preventDefault(); close(); }
    else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { e.preventDefault(); step(e.key === 'ArrowRight' ? 1 : -1); }
    return;
  }
  const i = thumbs.indexOf(document.activeElement);
  const d = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: 3, ArrowUp: -3 }[e.key];
  if (i < 0 || !d || !thumbs[i + d]) return;
  e.preventDefault();
  thumbs[i].tabIndex = -1;
  thumbs[i + d].tabIndex = 0;
  thumbs[i + d].focus();
});

render();
